  g2.setColor(Color.white); g2.fill(p);
  g2.setStroke(new BasicStroke(1, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
  g2.setColor(Color.black); g2.draw(p);
  ImageIO.write(dst, "png", new File(a[0]));
}}
