import javax.imageio.*; import java.awt.image.*; import java.io.*;
public class Cmp { public static void main(String[] a) throws Exception {
  BufferedImage x = ImageIO.read(new File(a[0])), y = ImageIO.read(new File(a[1]));
  if(x.getWidth()!=y.getWidth()||x.getHeight()!=y.getHeight()){System.out.println("SIZE DIFF "+x.getWidth()+"x"+x.getHeight()+" vs "+y.getWidth()+"x"+y.getHeight());return;}
  int n=0; int lim = a.length>2?Integer.parseInt(a[2]):20;
  for(int j=0;j<x.getHeight();j++) for(int i=0;i<x.getWidth();i++){ int p=x.getRGB(i,j), q=y.getRGB(i,j); if(p!=q){ if(n<lim) System.out.printf("(%d,%d) %08x %08x%n",i,j,p,q); n++;}}
  System.out.println(n==0?"IDENTICAL":("DIFF pixels: "+n));
}}
EOF
