import java.util.*;
public class FM11 { 
  public static void main(String[] a) throws Exception {
  BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
  Graphics2D g = image.createGraphics();
  int[][] d = {{4,3,1},{5,4,1},{7,7,1},{8,8,1},{9,9,1},{11,11,1},{12,13,1},{14,15,2},{15,16,1},{16,17,2},{18,19,2},{19,21,2},{21,23,2},{22,24,2},{23,25,2},{25,27,2},{26,28,3},{28,30,3},{30,32,3},{33,36,3},{36,39,4},{39,42,4},{42,45,5},{49,53,5},{56,60,6},{63,68,6},{70,75,8},{84,91,9}};
  FontRenderContext[] frcs = { g.getFontRenderContext(), new FontRenderContext(null,true,false), new FontRenderContext(null,false,true), new FontRenderContext(null,true,true),
    new FontRenderContext(null, RenderingHints.VALUE_TEXT_ANTIALIAS_ON, RenderingHints.VALUE_FRACTIONALMETRICS_OFF)};
  String[] meas = {"outlineInt","outline2Dheight","visual","glyphVisual","pixel","tlOutline","tlBounds","tlPixel"};
  for (String gl : new String[]{"Z","z","H","X","M","E"}) for (int fi=0; fi<frcs.length; fi++) for (int mi=0; mi<meas.length; mi++) for (int form=1; form<=2; form++) {
    FontRenderContext frc = frcs[fi]; int ok=0;
    for (int[] r : d){ Font ff=new Font("Dialog", Font.BOLD, 12).deriveFont((float)r[1]);
      GlyphVector gv = ff.createGlyphVector(frc, gl);
      TextLayout tl = new TextLayout(gl, ff, frc);
      double v;
      switch(mi){ case 0: v = gv.getOutline().getBounds().getHeight(); break;
        case 1: v = gv.getOutline().getBounds2D().getHeight(); break;
        case 2: v = gv.getVisualBounds().getHeight(); break;
        case 3: v = gv.getGlyphVisualBounds(0).getBounds2D().getHeight(); break;
        case 4: v = gv.getPixelBounds(frc,0,0).getHeight(); break;
        case 5: v = tl.getOutline(null).getBounds().getHeight(); break;
        case 6: v = tl.getBounds().getHeight(); break;
        default: v = tl.getPixelBounds(frc,0,0).getHeight(); }
      int z = (int) v;
      int h=r[0]; int yrel = h - r[2];
      int pred = form==1 ? h - Math.abs(h/2 - z/2) : h/2 + z/2;
      if (pred==yrel) ok++;
    }
    if(ok>=26) System.out.println(gl+" frc"+fi+" "+meas[mi]+" form"+form+" ok="+ok);
  }
}}
