/** A grid coordinate. Hash layout matters: iteration order of hashed sets depends on it. */
public final class Cell {
    public final int x;
    public final int y;

    public Cell(int x, int y) { this.x = x; this.y = y; }

    public Cell north() { return new Cell(x, y - 1); }
    public Cell south() { return new Cell(x, y + 1); }
    public Cell east() { return new Cell(x + 1, y); }
    public Cell west() { return new Cell(x - 1, y); }
    public Cell nw() { return new Cell(x - 1, y - 1); }
    public Cell ne() { return new Cell(x + 1, y - 1); }
    public Cell sw() { return new Cell(x - 1, y + 1); }
    public Cell se() { return new Cell(x + 1, y + 1); }

    public boolean isNorthOf(Cell o) { return y < o.y; }
    public boolean isSouthOf(Cell o) { return y > o.y; }
    public boolean isWestOf(Cell o) { return x < o.x; }
    public boolean isEastOf(Cell o) { return x > o.x; }

