        if (!(o instanceof Cell)) return false;
        Cell c = (Cell) o;
        return c.x == x && c.y == y;
    }

    @Override public int hashCode() { return (x << 16) | y; }

    @Override public String toString() { return "(" + x + ", " + y + ")"; }
}
