package ditaa;

import java.util.*;

/** Unordered (hash-ordered) collection of cells. */
public class CellSet implements Iterable<Cell> {
    public static final int TYPE_CLOSED = 0;
    public static final int TYPE_OPEN = 1;
    public static final int TYPE_MIXED = 2;
    public static final int TYPE_HAS_CLOSED_AREA = 3;
    public static final int TYPE_UNDETERMINED = 4;

    final Set<Cell> cells = new HashSet<Cell>();
    private int cachedType = TYPE_UNDETERMINED;
    private boolean typeKnown = false;

    public CellSet() {}

    public CellSet(CellSet other) { for (Cell c : other) add(c); }

    public Iterator<Cell> iterator() { return cells.iterator(); }

    public boolean add(Cell c) { typeKnown = false; return cells.add(c); }
    public void addAll(CellSet s) { typeKnown = false; for (Cell c : s) cells.add(c); }
    public boolean contains(Cell c) { return cells.contains(c); }
    public boolean remove(Cell c) { typeKnown = false; return cells.remove(c); }
    public int size() { return cells.size(); }
    public boolean isEmpty() { return cells.isEmpty(); }
    public void clear() { typeKnown = false; cells.clear(); }

    public Cell first() {
        Iterator<Cell> it = cells.iterator();
        return it.hasNext() ? it.next() : null;
    }

    public void subtract(CellSet other) {
        typeKnown = false;
        for (Cell c : other) cells.remove(c);
    }

    public boolean sameCellsAs(CellSet other) {
        if (other.size() != size()) return false;
        for (Cell c : this) if (!other.contains(c)) return false;
        return true;
    }

    public int minX() { int m = Integer.MAX_VALUE; for (Cell c : this) if (c.x < m) m = c.x; return m; }
    public int minY() { int m = Integer.MAX_VALUE; for (Cell c : this) if (c.y < m) m = c.y; return m; }
    public int maxX() { int m = Integer.MIN_VALUE; for (Cell c : this) if (c.x > m) m = c.x; return m; }
    public int maxY() { int m = Integer.MIN_VALUE; for (Cell c : this) if (c.y > m) m = c.y; return m; }

    public CellSet translated(int dx, int dy) {
        CellSet r = new CellSet();
        for (Cell c : this) r.add(new Cell(c.x + dx, c.y + dy));
        return r;
    }

    int getCachedType() { return typeKnown ? cachedType : -1; }
    void setCachedType(int t) { cachedType = t; typeKnown = true; }

    public static List<CellSet> removeDuplicates(List<CellSet> sets) {
        List<CellSet> result = new ArrayList<CellSet>();
        for (CellSet s : sets) {
            boolean dup = false;
            for (CellSet r : result) if (r.sameCellsAs(s)) { dup = true; break; }
            if (!dup) result.add(s);
        }
        return result;
    }

    @Override public String toString() { return cells.toString(); }
}
