package ditaa;

/**
 * A 3x3 neighbourhood matcher. Each position holds a token:
 *  '.' anything            'b' boundary char        '!' not a boundary char
 *  '-' horizontal line     '|' vertical line        '[' not a vertical line
 *  '~' not horiz. line     '^' boundary, not horiz. '(' boundary, not vertical
 *  '1'..'8' entry-point classes, anything else literal.
 */
final class Pattern3 {
    private final char[] tok = new char[9];

    Pattern3(String r0, String r1, String r2) {
        String all = r0 + r1 + r2;
        for (int i = 0; i < 9; i++) tok[i] = all.charAt(i);
    }

    static boolean isBoundaryChar(char c) {
        return c == '-' || c == '=' || c == '/' || c == '\\' || c == '+' || c == '|' || c == ':';
    }

    static boolean inEntry(int n, char c) {
        switch (n) {
            case 1: case 5: return c == '\\';
            case 3: case 7: return c == '/';
            case 2: case 6: return c == '|' || c == ':' || c == '+' || c == '\\' || c == '/';
            case 4: case 8: return c == '-' || c == '=' || c == '+' || c == '\\' || c == '/';
        }
        return false;
    }

    private static boolean tokenMatches(char t, char c) {
        switch (t) {
            case '.': return true;
            case 'b': return isBoundaryChar(c);
            case '!': return !isBoundaryChar(c);
            case '-': return c == '-' || c == '=';
            case '|': return c == '|' || c == ':';
            case '[': return !(c == '|' || c == ':');
            case '~': return !(c == '-' || c == '=');
            case '^': return isBoundaryChar(c) && !(c == '-' || c == '=');
            case '(': return isBoundaryChar(c) && !(c == '|' || c == ':');
            case 's': return c == '-' || c == '=' || c == '|' || c == ':';
            default:
                if (t >= '1' && t <= '8') return inEntry(t - '0', c);
                return t == c;
        }
    }

    boolean matches(Grid g, int x, int y) {
        int i = 0;
        for (int dy = -1; dy <= 1; dy++)
            for (int dx = -1; dx <= 1; dx++)
                if (!tokenMatches(tok[i++], g.get(x + dx, y + dy))) return false;
        return true;
    }
}
