package ditaa;

import java.io.PrintStream;
import java.util.*;

/** Character grid with the cell classification logic used for shape detection. */
public class Grid {
    private List<StringBuilder> rows = new ArrayList<StringBuilder>();

    public Grid() {}

    public Grid(int w, int h) {
        for (int i = 0; i < h; i++) rows.add(new StringBuilder(spaces(w)));
    }

    public Grid(Grid other) {
        for (StringBuilder r : other.rows) rows.add(new StringBuilder(r));
    }

    static String spaces(int n) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < n; i++) b.append(' ');
        return b.toString();
    }

    public List<StringBuilder> rows() { return rows; }
    public void setRows(List<StringBuilder> r) { rows = r; }

    public int width() { return rows.isEmpty() ? 0 : rows.get(0).length(); }
    public int height() { return rows.size(); }

    public char get(int x, int y) {
        if (y < 0 || y >= rows.size()) return 0;
        StringBuilder r = rows.get(y);
        if (x < 0 || x >= width() || x >= r.length()) return 0;
        return r.charAt(x);
    }
    public char get(Cell c) { return get(c.x, c.y); }

    public void set(int x, int y, char ch) {
        if (x < 0 || y < 0 || x > width() - 1 || y > height() - 1) return;
        rows.get(y).setCharAt(x, ch);
    }
    public void set(Cell c, char ch) { set(c.x, c.y, ch); }

    public boolean isOutOfBounds(Cell c) { return isOutOfBounds(c.x, c.y); }
    public boolean isOutOfBounds(int x, int y) { return x < 0 || y < 0 || x > width() - 1 || y > height() - 1; }

    public boolean isBlank(int x, int y) {
        char c = get(x, y);
        if (c == 0) return false;
        return c == ' ';
    }
    public boolean isBlank(Cell c) { return isBlank(c.x, c.y); }

    public Grid subGrid(int x, int y, int w, int h) {
        Grid g = new Grid(w, h);
        for (int j = 0; j < h; j++)
            for (int i = 0; i < w; i++) g.set(i, j, get(x + i, y + j));
        return g;
    }

    public void printDebug(PrintStream out) {
        StringBuilder head = new StringBuilder("    ");
        int reps = width() / 10 + 1;
        for (int i = 0; i < reps; i++) head.append("0123456789");
        out.println(head);
        int i = 0;
        for (StringBuilder r : rows) {
            String idx = Integer.toString(i);
            if (i < 10) idx = " " + idx;
            out.println(idx + " (" + r + ")");
            i++;
        }
    }

    public void copyCellsTo(CellSet cells, Grid target) {
        for (Cell c : cells) target.set(c, get(c));
    }

    public void fillCellsWith(CellSet cells, char ch) {
        for (Cell c : cells) set(c, ch);
    }

    public CellSet allNonBlank() {
        CellSet s = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (!isBlank(x, y)) s.add(new Cell(x, y));
        return s;
    }

    public CellSet allBoundaries() {
        CellSet s = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                Cell c = new Cell(x, y);
                if (isBoundary(c)) s.add(c);
            }
