        return r;
    }

    public CellSet followCrossOnLine(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        if (isHorizontalCrossOnLine(c)) {
            r.add(c.east());
            r.add(c.west());
        } else if (isVerticalCrossOnLine(c)) {
            r.add(c.north());
            r.add(c.south());
        }
        if (blocked != null) r.remove(blocked);
        return r;
    }

