    // preprocessing

    private boolean isOnHorizontalLine(int x, int y) {
        return isHorizontalLineChar(get(x - 1, y)) && isHorizontalLineChar(get(x + 1, y));
    }
    private boolean isOnVerticalLine(int x, int y) {
        return isVerticalLineChar(get(x, y - 1)) && isVerticalLineChar(get(x, y + 1));
    }

    public void replaceTypeOnLine() {
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                char c = get(x, y);
                if (Character.isLetter(c)) {
                    boolean hz = isOnHorizontalLine(x, y), vt = isOnVerticalLine(x, y);
                    if (hz && vt) set(x, y, '+');
                    else if (hz) set(x, y, '-');
                    else if (vt) set(x, y, '|');
                }
            }
    }

    public void replacePointMarkersOnLine() {
        int w = width(), h = height();
