                    if (hz && vt) set(x, y, '+');
                    else if (hz) set(x, y, '-');
                    else if (vt) set(x, y, '|');
                }
            }
    }

    public CellSet pointMarkersOnLine() {
        CellSet r = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                Cell cell = new Cell(x, y);
                if (get(x, y) == '*' && isStarOnLine(cell)) r.add(cell);
            }
        return r;
    }

    public CellSet arrowheads() {
        CellSet r = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                Cell cell = new Cell(x, y);
                if (isArrowhead(cell)) r.add(cell);
            }
        return r;
    }
