    public boolean isIntersection(Cell c) { return isCross(c) || isT(c) || isInverseT(c) || isK(c) || isInverseK(c); }

    public boolean isNormalCorner1(Cell c) { return any(NCORNER1, c); }
    public boolean isNormalCorner2(Cell c) { return any(NCORNER2, c); }
    public boolean isNormalCorner3(Cell c) { return any(NCORNER3, c); }
    public boolean isNormalCorner4(Cell c) { return any(NCORNER4, c); }
    public boolean isRoundCorner1(Cell c) { return any(RCORNER1, c); }
    public boolean isRoundCorner2(Cell c) { return any(RCORNER2, c); }
    public boolean isRoundCorner3(Cell c) { return any(RCORNER3, c); }
    public boolean isRoundCorner4(Cell c) { return any(RCORNER4, c); }
    public boolean isCorner1(Cell c) { return isNormalCorner1(c) || isRoundCorner1(c); }
    public boolean isCorner2(Cell c) { return isNormalCorner2(c) || isRoundCorner2(c); }
    public boolean isCorner3(Cell c) { return isNormalCorner3(c) || isRoundCorner3(c); }
    public boolean isCorner4(Cell c) { return isNormalCorner4(c) || isRoundCorner4(c); }
    public boolean isNormalCorner(Cell c) { return isNormalCorner1(c) || isNormalCorner2(c) || isNormalCorner3(c) || isNormalCorner4(c); }
    public boolean isRoundCorner(Cell c) { return isRoundCorner1(c) || isRoundCorner2(c) || isRoundCorner3(c) || isRoundCorner4(c); }
    public boolean isCorner(Cell c) { return isNormalCorner(c) || isRoundCorner(c); }

    public boolean isHorizontalCrossOnLine(Cell c) { return any(H_CROSS_ON_LINE, c); }
    public boolean isVerticalCrossOnLine(Cell c) { return any(V_CROSS_ON_LINE, c); }
    public boolean isCrossOnLine(Cell c) { return isHorizontalCrossOnLine(c) || isVerticalCrossOnLine(c); }
    public boolean isStub(Cell c) { return any(STUB, c); }
    public boolean isHorizontalLinesEnd(Cell c) { return any(H_LINES_END, c); }
    public boolean isVerticalLinesEnd(Cell c) { return any(V_LINES_END, c); }
    public boolean isLinesEnd(Cell c) { return isHorizontalLinesEnd(c) || isVerticalLinesEnd(c) || isStub(c); }
    public boolean isStarOnLine(Cell c) { return any(STAR_ON_LINE, c); }

    public boolean isHorizontalLine(Cell c) { return isHorizontalLineChar(get(c)); }
    public boolean isVerticalLine(Cell c) { return isVerticalLineChar(get(c)); }
    public boolean isLine(Cell c) { return isHorizontalLine(c) || isVerticalLine(c); }

    public boolean isNorthArrowhead(Cell c) { return get(c) == '^'; }
    public boolean isWestArrowhead(Cell c) { return get(c) == '<'; }
    public boolean isEastArrowhead(Cell c) { return get(c) == '>'; }
    public boolean isSouthArrowhead(Cell c) { char ch = get(c); return (ch == 'v' || ch == 'V') && isVerticalLine(c.north()); }
    public boolean isArrowhead(Cell c) { return isNorthArrowhead(c) || isSouthArrowhead(c) || isWestArrowhead(c) || isEastArrowhead(c); }

    public boolean isPointCell(Cell c) {
        return isCorner(c) || isIntersection(c) || isStub(c) || isLinesEnd(c);
    }

    public boolean isBoundary(Cell c) {
        char ch = get(c);
        if (ch == 0) return false;
        if (ch == '+' || ch == '\\' || ch == '/') {
            return isIntersection(c) || isCorner(c) || isStub(c) || isCrossOnLine(c);
        }
        return isBoundaryChar(ch) && !isLoneDiagonal(c);
    }

    public boolean isLoneDiagonal(Cell c) { return false; }

    public boolean hasEntryPoint(Cell c, int n) { return Pattern3.inEntry(n, get(c)); }

    public boolean cellContainsDashedLineChar(Cell c) { return isDashedChar(get(c)); }

    public boolean containsAtLeastOneDashedLine(CellSet set) {
        for (Cell c : set) if (isDashedChar(get(c))) return true;
        return false;
    }

    // ------------------------------------------------------------------
    // following lines

    public CellSet followCell(Cell c) { return followCell(c, null); }

    public CellSet followCell(Cell c, Cell blocked) {
        if (isIntersection(c)) return followIntersection(c, blocked);
        if (isCorner(c)) return followCorner(c, blocked);
        if (isLine(c)) return followLine(c, blocked);
        if (isStub(c)) return followStub(c, blocked);
        if (isCrossOnLine(c)) return followCrossOnLine(c, blocked);
        throw new IllegalStateException("Cannot follow cell " + c + ": cannot determine cell type");
    }

    public CellSet followIntersection(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        Cell n = c.north(), s = c.south(), e = c.east(), w = c.west();
        if (hasEntryPoint(n, 6)) r.add(n);
        if (hasEntryPoint(s, 2)) r.add(s);
        if (hasEntryPoint(e, 8)) r.add(e);
        if (hasEntryPoint(w, 4)) r.add(w);
        if (blocked != null) r.remove(blocked);
        return r;
    }

    private CellSet two(Cell a, Cell b, Cell blocked) {
        CellSet r = new CellSet();
        if (!a.equals(blocked)) r.add(a);
        if (!b.equals(blocked)) r.add(b);
        return r;
    }

    public CellSet followCorner(Cell c, Cell blocked) {
        if (isCorner1(c)) return two(c.south(), c.east(), blocked);
        if (isCorner2(c)) return two(c.south(), c.west(), blocked);
        if (isCorner3(c)) return two(c.north(), c.east(), blocked);
        if (isCorner4(c)) return two(c.north(), c.west(), blocked);
        return null;
    }

    public CellSet followLine(Cell c, Cell blocked) {
        if (isHorizontalLine(c)) return followHorizontalLine(c, blocked);
        if (isVerticalLine(c)) return followVerticalLine(c, blocked);
        return null;
    }

    public CellSet followHorizontalLine(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        Cell e = c.east(), w = c.west();
        if (hasEntryPoint(e, 8)) r.add(e);
        if (hasEntryPoint(w, 4)) r.add(w);
        if (blocked != null) r.remove(blocked);
        return r;
    }

    public CellSet followVerticalLine(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        Cell n = c.north(), s = c.south();
        if (hasEntryPoint(n, 6)) r.add(n);
        if (hasEntryPoint(s, 2)) r.add(s);
        if (blocked != null) r.remove(blocked);
        return r;
    }

    public CellSet followStub(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        Cell n = c.north(), s = c.south(), e = c.east(), w = c.west();
        if (hasEntryPoint(n, 6)) r.add(n);
        if (hasEntryPoint(s, 2)) r.add(s);
        if (hasEntryPoint(e, 8)) r.add(e);
        if (hasEntryPoint(w, 4)) r.add(w);
        if (blocked != null) r.remove(blocked);
        return r;
    }

    public CellSet followCrossOnLine(Cell c, Cell blocked) {
        CellSet r = new CellSet();
        if (isHorizontalCrossOnLine(c)) {
            r.add(c.east());
            r.add(c.west());
        } else if (isVerticalCrossOnLine(c)) {
            r.add(c.north());
            r.add(c.south());
        }
        if (blocked != null) r.remove(blocked);
        return r;
    }

    // ------------------------------------------------------------------
    // preprocessing

    private boolean isOnHorizontalLine(int x, int y) {
        return isHorizontalLineChar(get(x - 1, y)) && isHorizontalLineChar(get(x + 1, y));
    }
    private boolean isOnVerticalLine(int x, int y) {
        return isVerticalLineChar(get(x, y - 1)) && isVerticalLineChar(get(x, y + 1));
    }

    public void replaceTypeOnLine() {
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                char c = get(x, y);
                if (Character.isLetter(c)) {
                    boolean hz = isOnHorizontalLine(x, y), vt = isOnVerticalLine(x, y);
                    if (hz && vt) set(x, y, '+');
                    else if (hz) set(x, y, '-');
                    else if (vt) set(x, y, '|');
                }
            }
    }

    public void replacePointMarkersOnLine() {
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                char c = get(x, y);
                Cell cell = new Cell(x, y);
                if (c == '*' && isStarOnLine(cell)) {
                    boolean hz = isHorizontalLineChar(get(cell.east())) || isHorizontalLineChar(get(cell.west()));
                    boolean vt = isVerticalLineChar(get(cell.north())) || isVerticalLineChar(get(cell.south()));
                    if (hz && vt) set(x, y, '+');
                    else if (hz) set(x, y, '-');
                    else if (vt) set(x, y, '|');
                }
            }
    }

    public CellSet pointMarkersOnLine() {
        CellSet r = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                Cell cell = new Cell(x, y);
                if (get(x, y) == '*' && isStarOnLine(cell)) r.add(cell);
            }
        return r;
    }

    public CellSet arrowheads() {
        CellSet r = new CellSet();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                Cell cell = new Cell(x, y);
                if (isArrowhead(cell)) r.add(cell);
            }
        return r;
    }
}
