import java.awt.*;
import java.awt.font.FontRenderContext;
import java.awt.image.BufferedImage;

/** Font size search and text metrics. */
public final class FontMeasurer {
    static final String FAMILY = "Dialog";
    private static final FontMeasurer INSTANCE = new FontMeasurer();

    private final Graphics2D g;
    private final FontRenderContext frc;

    private FontMeasurer() {
        BufferedImage img = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
        g = img.createGraphics();
        frc = g.getFontRenderContext();
    }

    public static FontMeasurer instance() { return INSTANCE; }

    public FontRenderContext renderContext() { return frc; }

    public int widthFor(String s, Font f) {
        return g.getFontMetrics(f).stringWidth(s);
    }

    public int ascentFor(Font f) { return g.getFontMetrics(f).getAscent(); }

    public int zHeight(Font f) {
        return (int) f.createGlyphVector(frc, "Z").getOutline().getBounds().getHeight();
    }

    /** Biggest font (half-point steps) whose ascent fits the given pixel height. */
    public Font fontFor(int pixelHeight) {
        float size = 12;
        Font f = new Font(FAMILY, Font.BOLD, (int) size);
        int asc = ascentFor(f);
        int dir;
        if (asc > pixelHeight) { size -= 0.5f; f = f.deriveFont(size); dir = -1; }
        else { size += 0.5f; f = f.deriveFont(size); dir = 1; }
        while (size > 0) {
            f = f.deriveFont(size);
            asc = ascentFor(f);
            if (dir == 1) {
                if (asc > pixelHeight) { size -= 0.5f; return f.deriveFont(size); }
                size += 0.5f;
            } else {
                if (asc < pixelHeight) return f;
                size -= 0.5f;
            }
        }
        return null;
    }

    /** Biggest font (half-point steps) for which the string fits the width. */
    public Font fontFor(int maxWidth, String s) {
        float size = 12;
        Font f = new Font(FAMILY, Font.BOLD, (int) size);
        int w = widthFor(s, f);
        int dir;
        if (w > maxWidth) { size -= 0.5f; f = f.deriveFont(size); dir = -1; }
        else { size += 0.5f; f = f.deriveFont(size); dir = 1; }
        while (size > 0) {
            f = f.deriveFont(size);
            w = widthFor(s, f);
            if (dir == 1) {
                if (w > maxWidth) { size -= 0.5f; return f.deriveFont(size); }
                size += 0.5f;
            } else {
                if (w < maxWidth) return f;
                size -= 0.5f;
            }
        }
        return null;
    }
}
