    ShapeEdge(ShapePoint s, ShapePoint e, DiagramShape owner) { start = s; end = e; this.owner = owner; }

    int type() {
        if (start.y == end.y) return TYPE_HORIZONTAL;
        if (start.x == end.x) return TYPE_VERTICAL;
        return TYPE_UNDEFINED;
    }

    boolean touchesWith(ShapeEdge o) {
        if (this == o) return true;
        int t1 = type(), t2 = o.type();
        if (t1 == TYPE_UNDEFINED || t2 == TYPE_UNDEFINED) return false;
        if (t1 != t2) return false;
        float a1, a2, b1, b2;
        if (t1 == TYPE_HORIZONTAL) {
            if (start.y != o.start.y) return false;
            a1 = Math.min(start.x, end.x); a2 = Math.max(start.x, end.x);
            b1 = Math.min(o.start.x, o.end.x); b2 = Math.max(o.start.x, o.end.x);
        } else {
            if (start.x != o.start.x) return false;
            a1 = Math.min(start.y, end.y); a2 = Math.max(start.y, end.y);
            b1 = Math.min(o.start.y, o.end.y); b2 = Math.max(o.start.y, o.end.y);
        }
        return Math.max(a1, b1) < Math.min(a2, b2);
    }

    void moveInwardsBy(float offset) {
        int t = type();
        if (t == TYPE_UNDEFINED) throw new RuntimeException("Cannot move edge of type TYPE_UNDEFINED");
        GeneralPath path = owner.makeIntoPath();
        float mx = (start.x + end.x) / 2f, my = (start.y + end.y) / 2f;
        float eps = 0.5f;
        if (t == TYPE_HORIZONTAL) {
            if (path.contains(mx, my - eps)) { start.y -= offset; end.y -= offset; }
            else { start.y += offset; end.y += offset; }
        } else {
            if (path.contains(mx - eps, my)) { start.x -= offset; end.x -= offset; }
            else { start.x += offset; end.x += offset; }
        }
    }
}
