package ditaa;

import java.awt.Color;
import java.awt.Rectangle;
import java.awt.geom.Ellipse2D;
import java.awt.geom.GeneralPath;
import java.util.*;

public class DiagramShape {
    public static final int TYPE_SIMPLE = 0;
    public static final int TYPE_ARROWHEAD = 1;
    public static final int TYPE_POINT_MARKER = 2;
    public static final int TYPE_DOCUMENT = 3;
    public static final int TYPE_STORAGE = 4;
    public static final int TYPE_IO = 5;
    public static final int TYPE_DECISION = 6;
    public static final int TYPE_MANUAL_OPERATION = 7;
    public static final int TYPE_TRAPEZOID = 8;
    public static final int TYPE_ELLIPSE = 9;
    public static final int TYPE_CUSTOM = 10;

    static final float KAPPA = 4f * ((float) Math.sqrt(2) - 1) / 3f;

    private int type = TYPE_SIMPLE;
    private Color fillColor = null;
    private Color strokeColor = Color.black;
    private boolean closed = false;
    private boolean dashed = false;
    final ArrayList<ShapePoint> points = new ArrayList<ShapePoint>();

    public List<ShapePoint> getPoints() { return points; }
    public void addToPoints(ShapePoint p) { points.add(p); }
    public int getType() { return type; }
    public void setType(int t) { type = t; }
    public Color getFillColor() { return fillColor; }
    public void setFillColor(Color c) { fillColor = c; }
    public Color getStrokeColor() { return strokeColor; }
    public boolean isClosed() { return closed; }
    public void setClosed(boolean b) { closed = b; }
    public boolean isStrokeDashed() { return dashed; }
    public void setStrokeDashed(boolean b) { dashed = b; }

    public boolean dropsShadow() {
        return !dashed && closed && type != TYPE_ARROWHEAD && type != TYPE_POINT_MARKER;
    }

    // ------------------------------------------------------------------

    public static DiagramShape createArrowhead(Grid g, Cell c, int cw, int ch) {
        DiagramShape s = new DiagramShape();
        float x0 = c.x * cw, x1 = (c.x + 1) * cw, xm = c.x * cw + cw / 2;
        float y0 = c.y * ch, y1 = (c.y + 1) * ch, ym = c.y * ch + ch / 2;
        if (g.isNorthArrowhead(c)) {
            s.addToPoints(new ShapePoint(xm, y0));
            s.addToPoints(new ShapePoint(x0, y1));
            s.addToPoints(new ShapePoint(x1, y1));
        } else if (g.isSouthArrowhead(c)) {
            s.addToPoints(new ShapePoint(x0, y0));
            s.addToPoints(new ShapePoint(xm, y1));
            s.addToPoints(new ShapePoint(x1, y0));
        } else if (g.isWestArrowhead(c)) {
            s.addToPoints(new ShapePoint(x1, y0));
            s.addToPoints(new ShapePoint(x0, ym));
            s.addToPoints(new ShapePoint(x1, y1));
        } else if (g.isEastArrowhead(c)) {
            s.addToPoints(new ShapePoint(x0, y0));
            s.addToPoints(new ShapePoint(x1, ym));
            s.addToPoints(new ShapePoint(x0, y1));
        } else return null;
        s.setClosed(true);
        s.setType(TYPE_ARROWHEAD);
        s.setFillColor(Color.black);
        return s;
    }

    public static DiagramShape createSmallLine(Grid g, Cell c, int cw, int ch) {
        if (!g.isLine(c)) return null;
        DiagramShape s = new DiagramShape();
        if (g.isHorizontalLine(c)) {
            s.addToPoints(new ShapePoint(c.x * cw, c.y * ch + ch / 2));
            s.addToPoints(new ShapePoint(c.x * cw + cw - 1, c.y * ch + ch / 2));
        } else {
            s.addToPoints(new ShapePoint(c.x * cw + cw / 2, c.y * ch));
            s.addToPoints(new ShapePoint(c.x * cw + cw / 2, c.y * ch + ch - 1));
        }
        return s;
    }

    // ------------------------------------------------------------------

    public void connectEndsToAnchors(Grid g, Diagram d) {
        if (closed) return;
        connectEndToAnchors(g, d, true);
        connectEndToAnchors(g, d, false);
    }

    private void connectEndToAnchors(Grid g, Diagram d, boolean start) {
        if (closed || points.size() < 2) return;
        ShapePoint end, prev;
        if (start) { end = points.get(0); prev = points.get(1); }
        else { end = points.get(points.size() - 1); prev = points.get(points.size() - 2); }
        Cell anchor = possibleAnchorCell(end, prev, d);
        if (anchor == null) return;
        if (g.isArrowhead(anchor) || g.isCorner(anchor) || g.isIntersection(anchor)) {
            end.x = d.cellMidX(anchor);
            end.y = d.cellMidY(anchor);
        }
    }

    private Cell possibleAnchorCell(ShapePoint end, ShapePoint prev, Diagram d) {
        ShapePoint p = null;
        if (end.isNorthOf(prev)) p = new ShapePoint(end.x, end.y - d.getCellHeight());
        else if (end.isSouthOf(prev)) p = new ShapePoint(end.x, end.y + d.getCellHeight());
        else if (end.isWestOf(prev)) p = new ShapePoint(end.x - d.getCellWidth(), end.y);
        else if (end.isEastOf(prev)) p = new ShapePoint(end.x + d.getCellWidth(), end.y);
        if (p == null) throw new Diagram.ShapePointNullException();
        return d.cellFor(p);
    }

    // ------------------------------------------------------------------

    public ArrayList<ShapeEdge> getEdges() {
        ArrayList<ShapeEdge> edges = new ArrayList<ShapeEdge>();
        int n = points.size();
        if (n == 1) return edges;
        for (int i = 0; i < n - 1; i++) edges.add(new ShapeEdge(points.get(i), points.get(i + 1), this));
        if (closed) edges.add(new ShapeEdge(points.get(n - 1), points.get(0), this));
        return edges;
    }

    public GeneralPath makeIntoPath() {
        int n = points.size();
        if (n < 2) return null;
        GeneralPath path = new GeneralPath();
        ShapePoint p = points.get(0);
        path.moveTo(p.x, p.y);
        for (int i = 1; i < n; i++) { p = points.get(i); path.lineTo(p.x, p.y); }
        if (closed) path.closePath();
        return path;
    }

    public boolean contains(ShapePoint p) {
        GeneralPath path = makeIntoPath();
        if (path == null) return false;
        return path.contains(p);
    }

    public boolean intersects(java.awt.geom.Rectangle2D r) {
        GeneralPath path = makeIntoPath();
        if (path == null) return false;
        return path.intersects(r);
    }

    public double calculateArea() {
        int n = points.size();
        if (n == 0) return 0;
        double area = 0;
        for (int i = 0; i < n; i++) {
            ShapePoint a = points.get(i), b = points.get((i + 1) % n);
            area += (double) a.x * b.y - (double) b.x * a.y;
        }
        return Math.abs(area / 2);
    }

    public boolean isSmallerThan(DiagramShape o) { return calculateArea() < o.calculateArea(); }

    /** Equality by the set of (integer) point coordinates. */
    public boolean samePointsAs(DiagramShape o) {
        if (points.size() != o.points.size()) return false;
        HashSet<String> a = new HashSet<String>(), b = new HashSet<String>();
        for (ShapePoint p : points) a.add(((int) p.x) + "," + ((int) p.y));
        for (ShapePoint p : o.points) b.add(((int) p.x) + "," + ((int) p.y));
        return a.equals(b);
    }

    // ------------------------------------------------------------------
    // render paths

    public GeneralPath makeIntoRenderPath(Diagram d, RenderOptions opt) {
        int n = points.size();
        if (type == TYPE_POINT_MARKER) return makeMarkerPath(d);
        if (n == 4) {
            switch (type) {
                case TYPE_DOCUMENT: return makeDocumentPath(d);
                case TYPE_STORAGE: return makeStoragePath(d);
                case TYPE_IO: return makeIOPath(d, opt);
                case TYPE_DECISION: return makeDecisionPath(d);
                case TYPE_MANUAL_OPERATION: return makeManualOperationPath(d, opt);
                case TYPE_TRAPEZOID: return makeTrapezoidPath(d, opt);
                case TYPE_ELLIPSE: return makeEllipsePath(d);
            }
        }
        if (n < 2) return null;

        GeneralPath path = new GeneralPath();
        ShapePoint point = points.get(0);
        ShapePoint previous = points.get(n - 1);
        ShapePoint next = points.get(1);
        if (point.getType() == ShapePoint.TYPE_ROUND) {
            ShapePoint entry = cellEdgePointBetween(point, previous, d);
            ShapePoint exit = cellEdgePointBetween(point, next, d);
            path.moveTo(entry.x, entry.y);
            path.quadTo(point.x, point.y, exit.x, exit.y);
        } else {
            path.moveTo(point.x, point.y);
        }
        for (int i = 1; i < n; i++) {
            previous = point;
            point = points.get(i);
            next = (i < n - 1) ? points.get(i + 1) : points.get(0);
            if (point.getType() == ShapePoint.TYPE_ROUND) {
                ShapePoint entry = cellEdgePointBetween(point, previous, d);
                ShapePoint exit = cellEdgePointBetween(point, next, d);
                path.lineTo(entry.x, entry.y);
                path.quadTo(point.x, point.y, exit.x, exit.y);
                if (next.getType() == ShapePoint.TYPE_ROUND) {
                    ShapePoint ne = cellEdgePointBetween(next, point, d);
                    path.lineTo(ne.x, ne.y);
                } else {
                    path.lineTo(next.x, next.y);
                }
            } else {
                path.lineTo(point.x, point.y);
            }
        }
        if (closed) path.closePath();
        return path;
    }

    private ShapePoint cellEdgePointBetween(ShapePoint inCell, ShapePoint other, Diagram d) {
        ShapePoint r = null;
        if (other.isNorthOf(inCell)) r = new ShapePoint(inCell.x, inCell.y - d.getCellHeight() / 2);
        if (other.isSouthOf(inCell)) r = new ShapePoint(inCell.x, inCell.y + d.getCellHeight() / 2);
        if (other.isWestOf(inCell)) r = new ShapePoint(inCell.x - d.getCellWidth() / 2, inCell.y);
        if (other.isEastOf(inCell)) r = new ShapePoint(inCell.x + d.getCellWidth() / 2, inCell.y);
        if (r == null) throw new RuntimeException("Upexpected error, cannot find cell edge point");
        return r;
    }

    private GeneralPath makeMarkerPath(Diagram d) {
        ShapePoint c = points.get(0);
        float diameter = 0.7f * d.getMinimumOfCellDimension();
        GeneralPath path = new GeneralPath();
        path.append(new Ellipse2D.Float(c.x - diameter / 2, c.y - diameter / 2, diameter, diameter), false);
        return path;
    }

    private Rectangle bounds() { return makeIntoPath().getBounds(); }

    private GeneralPath makeDocumentPath(Diagram d) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        float mx = (float) b.getCenterX();
        GeneralPath path = new GeneralPath();
        path.moveTo(x1, y1);
        path.lineTo(x2, y1);
        path.lineTo(x2, y2);
        int cdx = b.width / 6;
        int cdy = b.height / 8;
        path.quadTo(mx + cdx, y2 - cdy, mx, y2);
        path.quadTo(mx - cdx, y2 + cdy, x1, y2);
        path.closePath();
        return path;
    }

    private GeneralPath makeStoragePath(Diagram d) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        int cdx = b.width / 6;
        int topDy = d.getCellHeight() / 2;
        int botDy = d.getCellHeight() * 5 / 7;
        GeneralPath path = new GeneralPath();
        path.moveTo(x1, y1);
        path.curveTo(x1 + cdx, y1 + topDy, x2 - cdx, y1 + topDy, x2, y1);
        path.curveTo(x2 - cdx, y1 - topDy, x1 + cdx, y1 - topDy, x1, y1);
        path.moveTo(x1, y1);
        path.lineTo(x1, y2);
        path.curveTo(x1 + cdx, y2 + botDy, x2 - cdx, y2 + botDy, x2, y2);
        path.lineTo(x2, y1);
        return path;
    }

    private float slantOffset(Diagram d, RenderOptions opt, Rectangle b) {
        if (opt.fixedSlope) return (float) b.getHeight() / 8f;
        return d.getCellWidth() / 2f;
    }

    private GeneralPath makeIOPath(Diagram d, RenderOptions opt) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        float off = slantOffset(d, opt, b);
        GeneralPath path = new GeneralPath();
        path.moveTo(x1 + off, y1);
        path.lineTo(x2 + off, y1);
        path.lineTo(x2 - off, y2);
        path.lineTo(x1 - off, y2);
        path.closePath();
        return path;
    }

    private GeneralPath makeDecisionPath(Diagram d) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        float cx = (float) b.getCenterX(), cy = (float) b.getCenterY();
        GeneralPath path = new GeneralPath();
        path.moveTo(x1, cy);
        path.lineTo(cx, y1);
        path.lineTo(x2, cy);
        path.lineTo(cx, y2);
        path.closePath();
        return path;
    }

    private GeneralPath makeManualOperationPath(Diagram d, RenderOptions opt) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        float off = slantOffset(d, opt, b);
        GeneralPath path = new GeneralPath();
        path.moveTo(x1 - off, y1);
        path.lineTo(x2 + off, y1);
        path.lineTo(x2 - off, y2);
        path.lineTo(x1 + off, y2);
        path.closePath();
        return path;
    }

    private GeneralPath makeTrapezoidPath(Diagram d, RenderOptions opt) {
        Rectangle b = bounds();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        float off = slantOffset(d, opt, b);
        GeneralPath path = new GeneralPath();
        path.moveTo(x1 + off, y1);
        path.lineTo(x2 - off, y1);
        path.lineTo(x2 + off, y2);
        path.lineTo(x1 - off, y2);
        path.closePath();
        return path;
    }

    private GeneralPath makeEllipsePath(Diagram d) {
        Rectangle b = bounds();
        float w = (float) b.getWidth(), h = (float) b.getHeight();
        float xOff = w * 0.5f * KAPPA, yOff = h * 0.5f * KAPPA;
        float cx = (float) b.getCenterX(), cy = (float) b.getCenterY();
        float x1 = (float) b.getMinX(), y1 = (float) b.getMinY(), x2 = (float) b.getMaxX(), y2 = (float) b.getMaxY();
        GeneralPath path = new GeneralPath();
        path.moveTo(cx, y1);
        path.curveTo(cx + xOff, y1, x2, cy - yOff, x2, cy);
        path.curveTo(x2, cy + yOff, cx + xOff, y2, cx, y2);
        path.curveTo(cx - xOff, y2, x1, cy + yOff, x1, cy);
        path.curveTo(x1, cy - yOff, cx - xOff, y1, cx, y1);
        path.closePath();
        return path;
    }
}
