package ditaa;

import java.util.*;

/** A 3x magnified grid where every boundary character is replaced by its line skeleton. */
public class Abstraction {
    private final Grid grid;

    private Abstraction(int w, int h) { grid = new Grid(w * 3, h * 3); }

    public Abstraction(Grid text, CellSet cells) {
        grid = new Grid(text.width() * 3, text.height() * 3);
        for (Cell c : cells) {
            if (text.isBlank(c)) continue;
            if (text.isCross(c)) put(c, CROSS);
            else if (text.isT(c)) put(c, T);
            else if (text.isK(c)) put(c, K);
            else if (text.isInverseT(c)) put(c, INV_T);
            else if (text.isInverseK(c)) put(c, INV_K);
            else if (text.isCorner1(c)) put(c, C1);
            else if (text.isCorner2(c)) put(c, C2);
            else if (text.isCorner3(c)) put(c, C3);
            else if (text.isCorner4(c)) put(c, C4);
            else if (text.isHorizontalLine(c)) put(c, HLINE);
            else if (text.isVerticalLine(c)) put(c, VLINE);
            else if (text.isCrossOnLine(c)) put(c, CROSS);
            else if (text.isStarOnLine(c)) put(c, STAR);
        }
    }

    // patterns as 3x3 strings, row-major
    static final String CROSS = " * *** * ";
    static final String T = "   *** * ";
    static final String INV_T = " * ***   ";
    static final String K = " *  ** * ";
    static final String INV_K = " * **  * ";
    static final String C1 = "    ** * ";
    static final String C2 = "   **  * ";
    static final String C3 = " *  **   ";
    static final String C4 = " * **    ";
    static final String HLINE = "   ***   ";
    static final String VLINE = " *  *  * ";
    static final String STAR = " * *** * ";

    private void put(Cell c, String pat) {
        int bx = c.x * 3, by = c.y * 3;
        for (int i = 0; i < 9; i++) {
            char ch = pat.charAt(i);
            if (ch != ' ') grid.set(bx + i % 3, by + i / 3, '*');
        }
    }

    public Grid copyOfInternalBuffer() { return new Grid(grid); }

    public int width() { return grid.width() / 3; }
    public int height() { return grid.height() / 3; }

    /** Splits the abstracted cells into connected shapes, returned in text-grid coordinates. */
    public List<CellSet> distinctShapes() {
        List<CellSet> result = new ArrayList<CellSet>();
        CellSet nonBlank = grid.allNonBlank();
        List<CellSet> distinct = CellSets.breakIntoDistinctBoundaries(nonBlank);
        for (CellSet set : distinct) {
            Abstraction temp = new Abstraction(width(), height());
            temp.grid.fillCellsWith(set, '*');
            result.add(temp.asTextGrid().allNonBlank());
        }
        return result;
    }

    private Grid asTextGrid() {
        Grid r = new Grid(width(), height());
        int w = grid.width(), h = grid.height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                if (!grid.isBlank(x, y)) r.set(x / 3, y / 3, '*');
        return r;
    }
}
