package ditaa;

import java.util.*;

/** Algorithms operating on cell sets. */
final class CellSets {
    private CellSets() {}

    /** Connected components (4-connectivity) of the set. */
    static List<CellSet> breakIntoDistinctBoundaries(CellSet set) {
        List<CellSet> result = new ArrayList<CellSet>();
        if (set.isEmpty()) return result;
        Grid g = new Grid(set.maxX() + 2, set.maxY() + 2);
        g.fillCellsWith(set, '*');
        for (Cell c : set) {
            if (g.isBlank(c.x, c.y)) continue;
            result.add(g.fillContinuousArea(c, ' '));
        }
        return result;
    }

    /** Connected components as seen through the abstraction of the given grid. */
    static List<CellSet> breakIntoDistinctBoundaries(CellSet set, Grid grid) {
        return new Abstraction(grid, set).distinctShapes();
    }

    static CellSet makeScaledOneThirdEquivalent(CellSet set) {
        CellSet r = new CellSet();
        for (Cell c : set) {
            if (c.x < 0 || c.y < 0) continue;
            if (c.x % 3 == 1 && c.y % 3 == 1) r.add(new Cell(c.x / 3, c.y / 3));
        }
        return r;
    }

    // ------------------------------------------------------------------
    // type determination

    static int getType(CellSet set, Grid grid) {
        int cached = set.getCachedType();
        if (cached >= 0) return cached;
        int t = computeType(set, grid);
        set.setCachedType(t);
        return t;
    }

    private static int computeType(CellSet set, Grid grid) {
        if (set.size() == 1) return CellSet.TYPE_OPEN;
        int trace = typeByTrace(set, grid);
        int fill = typeByFill(set, grid);
        if (fill == CellSet.TYPE_HAS_CLOSED_AREA) {
            if (trace == CellSet.TYPE_OPEN) return CellSet.TYPE_MIXED;
            if (trace == CellSet.TYPE_CLOSED) return CellSet.TYPE_CLOSED;
        } else if (fill == CellSet.TYPE_OPEN) {
            return CellSet.TYPE_OPEN;
        }
        return CellSet.TYPE_UNDETERMINED;
    }

    private static int typeByTrace(CellSet set, Grid grid) {
        if (set.size() < 2) return CellSet.TYPE_OPEN;
        Grid work = new Grid(grid.width(), grid.height());
        grid.copyCellsTo(set, work);
        Cell start = null;
        for (Cell c : set) if (work.isLinesEnd(c)) start = c;
        if (start == null) start = set.first();
        Cell previous = start;
        CellSet next = work.followCell(previous);
        if (next.size() == 0) return CellSet.TYPE_OPEN;
        Cell cell = next.first();
        while (!cell.equals(start)) {
            next = work.followCell(cell, previous);
            if (next.size() == 0) return CellSet.TYPE_OPEN;
            if (next.size() == 1) {
                previous = cell;
                cell = next.first();
            } else {
                return CellSet.TYPE_OPEN;
            }
        }
        return CellSet.TYPE_CLOSED;
    }

    private static int typeByFill(CellSet set, Grid grid) {
        if (set.size() == 0) return CellSet.TYPE_OPEN;
        int minX = set.minX(), minY = set.minY();
        CellSet temp = set.translated(-minX + 1, -minY + 1);
        int w = set.maxX() - minX + 1, h = set.maxY() - minY + 1;
        Grid sub = grid.subGrid(minX - 1, minY - 1, w + 3, h + 3);
        Grid t = new Abstraction(sub, temp).copyOfInternalBuffer();
        Cell fillCell = null;
        for (int y = 0; y < t.height(); y++)
            for (int x = 0; x < t.width(); x++)
                if (t.isBlank(x, y)) { fillCell = new Cell(x, y); break; }
        if (fillCell == null) return CellSet.TYPE_UNDETERMINED;
        t.fillContinuousArea(fillCell, '*');
        for (int y = 0; y < t.height(); y++)
            for (int x = 0; x < t.width(); x++)
                if (t.isBlank(x, y)) return CellSet.TYPE_HAS_CLOSED_AREA;
        return CellSet.TYPE_OPEN;
    }

    // ------------------------------------------------------------------

    static CellSet filledEquivalent(CellSet set, Grid textGrid) {
        if (getType(set, textGrid) == CellSet.TYPE_OPEN) return new CellSet(set);
        Grid g = new Grid(set.maxX() + 2, set.maxY() + 2);
        g.fillCellsWith(set, '*');
        Cell cell = null;
        boolean found = false;
        for (int y = 0; y < g.height() && !found; y++)
            for (int x = 0; x < g.width() && !found; x++) {
                cell = new Cell(x, y);
                if (!g.isBlank(cell) && g.isBlank(cell.east()) && g.isBlank(cell.west())) found = true;
            }
        if (cell != null) {
            cell = cell.east();
            if (g.isOutOfBounds(cell)) return new CellSet(set);
            g.fillContinuousArea(cell, '*');
            return g.allNonBlank();
        }
        return null;
    }

    static boolean hasCommonCells(CellSet a, CellSet b) {
        for (Cell c : a) if (b.contains(c)) return true;
        return false;
    }

    static List<CellSet> breakTrulyMixedBoundaries(CellSet set, Grid grid) {
        List<CellSet> result = new ArrayList<CellSet>();
        CellSet visitedEnds = new CellSet();
        Grid work = new Grid(grid.width(), grid.height());
        grid.copyCellsTo(set, work);
        for (Cell start : set) {
            if (work.isLinesEnd(start) && !visitedEnds.contains(start)) {
                CellSet s = new CellSet();
                s.add(start);
                Cell previous = start;
                CellSet next = work.followCell(previous);
                if (next.size() == 0)
                    throw new IllegalArgumentException("This shape is either open but multipart or has only one cell, and cannot be processed by this method");
                Cell cell = next.first();
                s.add(cell);
                boolean finished = false;
                if (work.isLinesEnd(cell)) { visitedEnds.add(cell); finished = true; }
                while (!finished) {
                    next = work.followCell(cell, previous);
                    if (next.size() == 1) {
                        s.add(cell);
                        previous = cell;
                        cell = next.first();
                        if (work.isLinesEnd(cell)) { visitedEnds.add(cell); finished = true; }
                    } else if (next.size() > 1) {
                        finished = true;
                    } else {
                        finished = true;
                    }
                }
                result.add(s);
            }
        }
        CellSet rest = new CellSet(set);
        for (CellSet s : result) rest.subtract(s);
        result.add(rest);
        return result;
    }
}
