            cell = cell.east();
            if (g.isOutOfBounds(cell)) return new CellSet(set);
            g.fillContinuousArea(cell, '*');
            return g.allNonBlank();
        }
        return null;
    }

    static boolean hasCommonCells(CellSet a, CellSet b) {
        for (Cell c : a) if (b.contains(c)) return true;
        return false;
    }

    static List<CellSet> breakTrulyMixedBoundaries(CellSet set, Grid grid) {
        List<CellSet> result = new ArrayList<CellSet>();
        CellSet visitedEnds = new CellSet();
        Grid work = new Grid(grid.width(), grid.height());
        grid.copyCellsTo(set, work);
        for (Cell start : set) {
