package ditaa;

import java.util.*;

public class CompositeShape {
    final ArrayList<DiagramShape> shapes = new ArrayList<DiagramShape>();

    public List<DiagramShape> getShapes() { return shapes; }

    public void connectEndsToAnchors(Grid g, Diagram d) {
        for (DiagramShape s : shapes) s.connectEndsToAnchors(g, d);
    }

    static CompositeShape createOpenFromBoundaryCells(Grid grid, CellSet cells, int cw, int ch, boolean allRound) {
        if (CellSets.getType(cells, grid) != CellSet.TYPE_OPEN)
            throw new IllegalArgumentException("This shape is closed and cannot be handled by this method");
        if (cells.size() == 0) return null;
        CompositeShape comp = new CompositeShape();
        Grid work = new Grid(grid.width(), grid.height());
        grid.copyCellsTo(cells, work);
        CellSet visited = new CellSet();
        List<DiagramShape> list = new ArrayList<DiagramShape>();
        for (Cell c : cells) {
            if (work.isLinesEnd(c)) {
                CellSet next = work.followCell(c);
                list.addAll(growEdges(work, cw, ch, allRound, next.first(), c, visited));
                break;
            }
        }
        boolean dashed = false;
        for (DiagramShape s : list) if (s.isStrokeDashed()) dashed = true;
        for (DiagramShape s : list) {
            if (dashed) s.setStrokeDashed(true);
            comp.shapes.add(s);
        }
        return comp;
    }

    private static List<DiagramShape> growEdges(Grid work, int cw, int ch, boolean allRound, Cell cell, Cell previous, CellSet visited) {
        List<DiagramShape> result = new ArrayList<DiagramShape>();
        visited.add(previous);
        DiagramShape shape = new DiagramShape();
        shape.addToPoints(Diagram.makePointForCell(previous, work, cw, ch, allRound));
        if (work.cellContainsDashedLineChar(previous)) shape.setStrokeDashed(true);
        boolean finished = false;
        while (!finished) {
            visited.add(cell);
            if (work.isPointCell(cell)) shape.addToPoints(Diagram.makePointForCell(cell, work, cw, ch, allRound));
            if (work.cellContainsDashedLineChar(cell)) shape.setStrokeDashed(true);
            if (work.isLinesEnd(cell)) finished = true;
            CellSet next = work.followCell(cell, previous);
            if (next.size() == 1) {
                previous = cell;
                cell = next.first();
            } else {
                finished = true;
                for (Cell n : next) {
                    if (!visited.contains(n))
                        result.addAll(growEdges(work, cw, ch, allRound, n, cell, visited));
                }
            }
        }
        result.add(shape);
        return result;
    }
}
