    private static final java.util.regex.Pattern COLOR_CODE = java.util.regex.Pattern.compile("c[A-F0-9]{3}");
    private static final java.util.regex.Pattern TAG = java.util.regex.Pattern.compile("\\\\{(.+?)\\\\}");
    static final Set<String> MARKUP_TAGS = new HashSet<String>(Arrays.asList("d", "s", "io", "c", "mo", "tr", "o"));

    public String stringAt(int x, int y, int len) {
        if (x > width() - 1 || y > height() - 1 || x < 0 || y < 0) return null;
        return rows.get(y).substring(x, x + len);
    }

    public List<ColorAt> findColorCodes() {
        List<ColorAt> r = new ArrayList<ColorAt>();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w - 3; x++) {
                String s = stringAt(x, y, 4);
                if (COLOR_CODE.matcher(s).matches()) {
                    int cr = Integer.parseInt(String.valueOf(s.charAt(1)), 16) * 17;
                    int cg = Integer.parseInt(String.valueOf(s.charAt(2)), 16) * 17;
                    int cb = Integer.parseInt(String.valueOf(s.charAt(3)), 16) * 17;
                    r.add(new ColorAt(new Cell(x, y), new java.awt.Color(cr, cg, cb)));
                }
            }
        return r;
    }

    public List<TagAt> findMarkupTags() {
        List<TagAt> r = new ArrayList<TagAt>();
        int w = width(), h = height();
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w - 3; x++) {
                if (get(x, y) == '{') {
                    String part = rows.get(y).substring(x);
                    java.util.regex.Matcher m = TAG.matcher(part);
                    if (m.find()) {
                        String tag = m.group(1);
                        if (MARKUP_TAGS.contains(tag)) r.add(new TagAt(new Cell(x, y), tag));
                    }
                }
            }
