    static ShapePoint makePointForCell(Cell c, Grid g, int cw, int ch, boolean allRound) {
        float x = c.x * cw + cw / 2, y = c.y * ch + ch / 2;
        if (g.isCorner(c) && allRound) return new ShapePoint(x, y, ShapePoint.TYPE_ROUND);
        if (g.isNormalCorner(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        if (g.isRoundCorner(c)) return new ShapePoint(x, y, ShapePoint.TYPE_ROUND);
        if (g.isLinesEnd(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        if (g.isIntersection(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        throw new RuntimeException("Cannot make point for cell " + c);
    }

    public Diagram(Grid grid, RenderOptions ro, ProcessOptions po) {
        cellWidth = ro.cellWidth();
        cellHeight = ro.cellHeight();
        width = grid.width() * cellWidth;
        height = grid.height() * cellHeight;

        Grid workGrid = new Grid(grid);
        workGrid.replaceTypeOnLine();
        workGrid.replacePointMarkersOnLine();

        int w = grid.width(), h = grid.height();

        Abstraction temp = new Abstraction(workGrid, workGrid.allBoundaries());
        List<CellSet> step1 = temp.distinctShapes();

        List<CellSet> step2 = new ArrayList<CellSet>();
        for (CellSet set : step1) {
            Grid fillBuffer = new Grid(w * 3, h * 3);
            for (int yi = 0; yi < h * 3; yi++) {
                for (int xi = 0; xi < w * 3; xi++) {
                    if (fillBuffer.isBlank(xi, yi)) {
                        Grid copy = new Abstraction(workGrid, set).copyOfInternalBuffer();
                        CellSet boundaries = copy.findBoundariesExpandingFrom(new Cell(xi, yi));
                        if (boundaries.size() == 0) continue;
                        step2.add(CellSets.makeScaledOneThirdEquivalent(boundaries));
                        copy = new Abstraction(workGrid, set).copyOfInternalBuffer();
                        CellSet filled = copy.fillContinuousArea(new Cell(xi, yi), '*');
                        fillBuffer.fillCellsWith(filled, '*');
                        fillBuffer.fillCellsWith(boundaries, '-');
                    }
