package ditaa;

import java.awt.Color;
import java.awt.Font;
import java.util.*;

/** Converts a text grid into shapes and text objects. */
public class Diagram {
    static final class ShapePointNullException extends IllegalArgumentException {
        ShapePointNullException() { super("ShapePoint cannot be null"); }
    }

    private final ArrayList<DiagramShape> shapes = new ArrayList<DiagramShape>();
    private final ArrayList<CompositeShape> compositeShapes = new ArrayList<CompositeShape>();
    private final ArrayList<DText> textObjects = new ArrayList<DText>();
    private final int width, height, cellWidth, cellHeight;

    public int getWidth() { return width; }
    public int getHeight() { return height; }
    public int getCellWidth() { return cellWidth; }
    public int getCellHeight() { return cellHeight; }
    public int getMinimumOfCellDimension() { return Math.min(cellWidth, cellHeight); }
    public List<DiagramShape> getShapes() { return shapes; }
    public List<DText> getTextObjects() { return textObjects; }

    public ArrayList<DiagramShape> getAllDiagramShapes() {
        ArrayList<DiagramShape> r = new ArrayList<DiagramShape>(shapes);
        for (CompositeShape c : compositeShapes) r.addAll(c.getShapes());
        return r;
    }

    public int cellMinX(Cell c) { return c.x * cellWidth; }
    public int cellMidX(Cell c) { return c.x * cellWidth + cellWidth / 2; }
    public int cellMaxX(Cell c) { return c.x * cellWidth + cellWidth; }
    public int cellMinY(Cell c) { return c.y * cellHeight; }
    public int cellMidY(Cell c) { return c.y * cellHeight + cellHeight / 2; }
    public int cellMaxY(Cell c) { return c.y * cellHeight + cellHeight; }

    public Cell cellFor(ShapePoint p) {
        if (p == null) throw new ShapePointNullException();
        return new Cell((int) p.x / cellWidth, (int) p.y / cellHeight);
    }

    static ShapePoint makePointForCell(Cell c, Grid g, int cw, int ch, boolean allRound) {
        float x = c.x * cw + cw / 2, y = c.y * ch + ch / 2;
        if (g.isCorner(c) && allRound) return new ShapePoint(x, y, ShapePoint.TYPE_ROUND);
        if (g.isNormalCorner(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        if (g.isRoundCorner(c)) return new ShapePoint(x, y, ShapePoint.TYPE_ROUND);
        if (g.isLinesEnd(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        if (g.isIntersection(c)) return new ShapePoint(x, y, ShapePoint.TYPE_NORMAL);
        throw new RuntimeException("Cannot make point for cell " + c);
    }

    public Diagram(Grid grid, RenderOptions ro, ProcessOptions po) {
        cellWidth = ro.cellWidth();
        cellHeight = ro.cellHeight();
        width = grid.width() * cellWidth;
        height = grid.height() * cellHeight;

        Grid workGrid = new Grid(grid);
        workGrid.replaceTypeOnLine();
        workGrid.replacePointMarkersOnLine();

        int w = grid.width(), h = grid.height();

        Abstraction temp = new Abstraction(workGrid, workGrid.allBoundaries());
        List<CellSet> step1 = temp.distinctShapes();

        List<CellSet> step2 = new ArrayList<CellSet>();
        for (CellSet set : step1) {
            Grid fillBuffer = new Grid(w * 3, h * 3);
            for (int yi = 0; yi < h * 3; yi++) {
                for (int xi = 0; xi < w * 3; xi++) {
                    if (fillBuffer.isBlank(xi, yi)) {
                        Grid copy = new Abstraction(workGrid, set).copyOfInternalBuffer();
                        CellSet boundaries = copy.findBoundariesExpandingFrom(new Cell(xi, yi));
                        if (boundaries.size() == 0) continue;
                        step2.add(CellSets.makeScaledOneThirdEquivalent(boundaries));
                        copy = new Abstraction(workGrid, set).copyOfInternalBuffer();
                        CellSet filled = copy.fillContinuousArea(new Cell(xi, yi), '*');
                        fillBuffer.fillCellsWith(filled, '*');
                        fillBuffer.fillCellsWith(boundaries, '-');
                    }
                }
            }
        }
        step2 = CellSets_removeDuplicates(step2);

        List<CellSet> open = new ArrayList<CellSet>(), closed = new ArrayList<CellSet>(), mixed = new ArrayList<CellSet>();
        classify(step2, workGrid, open, closed, mixed);

        boolean hadToEliminateMixed = false;
        if (mixed.size() > 0 && closed.size() > 0) {
            hadToEliminateMixed = true;
            for (CellSet set : mixed) {
                for (CellSet c : closed) set.subtract(c);
                if (CellSets.getType(set, workGrid) == CellSet.TYPE_OPEN) {
                    step2.remove(set);
                    step2.addAll(CellSets.breakIntoDistinctBoundaries(set, workGrid));
                }
            }
        } else if (mixed.size() > 0 && closed.size() == 0) {
            hadToEliminateMixed = true;
            for (CellSet set : mixed) {
                step2.remove(set);
                step2.addAll(CellSets.breakTrulyMixedBoundaries(set, workGrid));
            }
        }
        if (hadToEliminateMixed) {
            open = new ArrayList<CellSet>(); closed = new ArrayList<CellSet>(); mixed = new ArrayList<CellSet>();
            classify(step2, workGrid, open, closed, mixed);
        }

        removeObsoleteShapes(workGrid, closed);

        boolean allRound = po.allCornersRound;

        ArrayList<DiagramShape> closedShapes = new ArrayList<DiagramShape>();
        for (CellSet set : closed) {
            DiagramShape s = createClosedFromBoundaryCells(workGrid, set, cellWidth, cellHeight, allRound);
            if (s != null) {
                shapes.add(s);
                closedShapes.add(s);
            }
        }

        if (po.separateCommonEdges) separateCommonEdges(closedShapes);

        for (CellSet set : open) {
            if (set.size() == 1) {
                Cell c = set.first();
                if (!grid.cellContainsDashedLineChar(c)) {
                    DiagramShape s = DiagramShape.createSmallLine(workGrid, c, cellWidth, cellHeight);
                    if (s != null) {
                        shapes.add(s);
                        s.connectEndsToAnchors(workGrid, this);
                    }
                }
            } else {
                CompositeShape cs = CompositeShape.createOpenFromBoundaryCells(workGrid, set, cellWidth, cellHeight, allRound);
                if (cs != null) {
                    compositeShapes.add(cs);
                    cs.connectEndsToAnchors(workGrid, this);
                }
            }
        }

        for (Grid.ColorAt p : grid.findColorCodes()) {
            ShapePoint pt = new ShapePoint(cellMidX(p.cell), cellMidY(p.cell));
            DiagramShape s = findSmallestShapeContaining(pt);
            if (s != null) s.setFillColor(p.color);
        }

        for (Grid.TagAt p : grid.findMarkupTags()) {
            ShapePoint pt = new ShapePoint(cellMidX(p.cell), cellMidY(p.cell));
            DiagramShape s = findSmallestShapeContaining(pt);
            if (s == null) continue;
            String t = p.tag;
            if (t.equals("d")) s.setType(DiagramShape.TYPE_DOCUMENT);
            else if (t.equals("s")) s.setType(DiagramShape.TYPE_STORAGE);
            else if (t.equals("io")) s.setType(DiagramShape.TYPE_IO);
            else if (t.equals("c")) s.setType(DiagramShape.TYPE_DECISION);
            else if (t.equals("mo")) s.setType(DiagramShape.TYPE_MANUAL_OPERATION);
            else if (t.equals("tr")) s.setType(DiagramShape.TYPE_TRAPEZOID);
            else if (t.equals("o")) s.setType(DiagramShape.TYPE_ELLIPSE);
        }

        for (Cell c : workGrid.arrowheadList()) {
            DiagramShape a = DiagramShape.createArrowhead(workGrid, c, cellWidth, cellHeight);
            if (a != null) shapes.add(a);
            else System.err.println("Could not create arrowhead shape. Unexpected error.");
        }

        for (Cell c : grid.pointMarkersOnLine()) {
            DiagramShape m = new DiagramShape();
            m.addToPoints(new ShapePoint(cellMidX(c), cellMidY(c)));
            m.setType(DiagramShape.TYPE_POINT_MARKER);
            m.setFillColor(Color.white);
            shapes.add(m);
        }

        removeDuplicateShapes();

        // ---- text ----
        workGrid = new Grid(grid);
        workGrid.removeNonText();

        Grid textGroupGrid = new Grid(workGrid);
        CellSet gaps = textGroupGrid.allBlanksBetweenCharacters();
        textGroupGrid.fillCellsWith(gaps, '|');
        CellSet nonBlank = textGroupGrid.allNonBlank();
        List<CellSet> textGroups = CellSets.breakIntoDistinctBoundaries(nonBlank);

        Font font = FontMeasurer.instance().fontFor(cellHeight);

        for (CellSet group : textGroups) {
            Grid iso = new Grid(w, h);
            workGrid.copyCellsTo(group, iso);
            for (Grid.StringAt pair : iso.findStrings()) {
                Cell cell = pair.cell;
                String str = pair.text;
                Cell last = new Cell(cell.x + str.length() - 1, cell.y);
                int minX = cellMinX(cell);
                int y = cellMaxY(cell);
                int maxX = cellMaxX(last);
                DText t;
                if (FontMeasurer.instance().widthFor(str, font) > maxX - minX) {
                    Font less = FontMeasurer.instance().fontFor(maxX - minX, str);
                    t = new DText(minX, y, str, less);
                } else t = new DText(minX, y, str, font);
                t.centerVerticallyBetween(cellMinY(cell), cellMaxY(cell));
                int otherStart = iso.otherStringsStartInTheSameColumn(cell);
                int otherEnd = iso.otherStringsEndInTheSameColumn(last);
                if (otherStart == 0 && otherEnd == 0) {
                    t.centerHorizontallyBetween(minX, maxX);
                } else if (otherEnd > 0 && otherStart == 0) {
                    t.alignRightEdgeTo(maxX);
                } else if (otherEnd > 0 && otherStart > 0) {
                    if (otherEnd > otherStart) t.alignRightEdgeTo(maxX);
                    else if (otherEnd == otherStart) t.centerHorizontallyBetween(minX, maxX);
                }
                textObjects.add(t);
            }
        }

        for (DText t : textObjects) {
            DiagramShape s = findSmallestShapeIntersecting(t.getBounds());
            if (s != null && s.getFillColor() != null && BitmapRenderer.isColorDark(s.getFillColor()))
                t.setColor(Color.white);
        }
    }

    private static List<CellSet> CellSets_removeDuplicates(List<CellSet> l) { return CellSet.removeDuplicates(l); }

    private static void classify(List<CellSet> sets, Grid g, List<CellSet> open, List<CellSet> closed, List<CellSet> mixed) {
        for (CellSet s : sets) {
            int t = CellSets.getType(s, g);
            if (t == CellSet.TYPE_CLOSED) closed.add(s);
            else if (t == CellSet.TYPE_OPEN) open.add(s);
            else if (t == CellSet.TYPE_MIXED) mixed.add(s);
        }
    }

    private DiagramShape findSmallestShapeContaining(ShapePoint p) {
        DiagramShape found = null;
        for (DiagramShape s : shapes) {
            if (s.contains(p)) {
                if (found == null) found = s;
                else if (s.isSmallerThan(found)) found = s;
            }
        }
        return found;
    }

    private DiagramShape findSmallestShapeIntersecting(java.awt.geom.Rectangle2D r) {
        DiagramShape found = null;
        for (DiagramShape s : shapes) {
            if (s.intersects(r)) {
                if (found == null) found = s;
                else if (s.isSmallerThan(found)) found = s;
            }
        }
        return found;
    }

    private void removeDuplicateShapes() {
        ArrayList<DiagramShape> originals = new ArrayList<DiagramShape>();
        for (DiagramShape s : shapes) {
            boolean orig = true;
            for (DiagramShape o : originals) if (s.samePointsAs(o)) orig = false;
            if (orig) originals.add(s);
        }
        shapes.clear();
        shapes.addAll(originals);
    }

    private void separateCommonEdges(List<DiagramShape> list) {
        float offset = getMinimumOfCellDimension() / 5;
        ArrayList<ShapeEdge> edges = new ArrayList<ShapeEdge>();
        for (DiagramShape s : list) edges.addAll(s.getEdges());
        ArrayList<ShapeEdge[]> pairs = new ArrayList<ShapeEdge[]>();
        int startIndex = 1;
        for (ShapeEdge e1 : edges) {
            for (int k = startIndex; k < edges.size(); k++) {
                ShapeEdge e2 = edges.get(k);
                if (e1.touchesWith(e2)) pairs.add(new ShapeEdge[]{e1, e2});
            }
            startIndex++;
        }
        ArrayList<ShapeEdge> moved = new ArrayList<ShapeEdge>();
        for (ShapeEdge[] p : pairs) {
            if (!moved.contains(p[0])) { p[0].moveInwardsBy(offset); moved.add(p[0]); }
            if (!moved.contains(p[1])) { p[1].moveInwardsBy(offset); moved.add(p[1]); }
        }
    }

    private void removeObsoleteShapes(Grid grid, List<CellSet> sets) {
        ArrayList<CellSet> filledSets = new ArrayList<CellSet>();
        for (CellSet s : sets) {
            CellSet f = CellSets.filledEquivalent(s, grid);
            if (f == null) return;
            filledSets.add(f);
        }
        ArrayList<Integer> toRemove = new ArrayList<Integer>();
        for (CellSet set : filledSets) {
            ArrayList<CellSet> common = new ArrayList<CellSet>();
            common.add(set);
            for (CellSet s2 : filledSets) if (set != s2 && CellSets.hasCommonCells(set, s2)) common.add(s2);
            if (common.size() == 2) continue;
            CellSet largest = set;
            for (CellSet s2 : common) if (s2.size() > largest.size()) largest = s2;
            common.remove(largest);
            Grid smalls = new Grid(largest.maxX() + 2, largest.maxY() + 2);
            for (CellSet s2 : common) smalls.fillCellsWith(s2, '*');
            Grid big = new Grid(largest.maxX() + 2, largest.maxY() + 2);
            big.fillCellsWith(largest, '*');
            int index = filledSets.indexOf(largest);
            if (sameContent(big, smalls) && !toRemove.contains(index)) toRemove.add(index);
        }
        ArrayList<CellSet> removeSets = new ArrayList<CellSet>();
        for (int i : toRemove) removeSets.add(sets.get(i));
        for (CellSet s : removeSets) sets.remove(s);
    }

    private static boolean sameContent(Grid a, Grid b) {
        if (a.width() != b.width() || a.height() != b.height()) return false;
        for (int y = 0; y < a.height(); y++)
            for (int x = 0; x < a.width(); x++)
                if (a.get(x, y) != b.get(x, y)) return false;
        return true;
    }

    static DiagramShape createClosedFromBoundaryCells(Grid grid, CellSet cells, int cw, int ch, boolean allRound) {
        if (cells.size() < 2) return null;
        DiagramShape shape = new DiagramShape();
        shape.setClosed(true);
        if (grid.containsAtLeastOneDashedLine(cells)) shape.setStrokeDashed(true);
        Grid work = new Grid(grid.width(), grid.height());
        grid.copyCellsTo(cells, work);
        Cell start = cells.first();
        if (work.isCorner(start)) shape.addToPoints(makePointForCell(start, work, cw, ch, allRound));
        Cell previous = start;
        CellSet next = work.followCell(previous);
        if (next.size() == 0) return null;
        Cell cell = next.first();
        if (work.isCorner(cell)) shape.addToPoints(makePointForCell(cell, work, cw, ch, allRound));
        while (!cell.equals(start)) {
            next = work.followCell(cell, previous);
            if (next.size() == 1) {
                previous = cell;
                cell = next.first();
                if (!cell.equals(start) && work.isCorner(cell))
                    shape.addToPoints(makePointForCell(cell, work, cw, ch, allRound));
            } else if (next.size() > 1) {
                return null;
            } else {
                return null;
            }
        }
        return shape;
    }
}
