package ditaa;

import java.awt.*;
import java.awt.geom.AffineTransform;
import java.awt.geom.GeneralPath;
import java.awt.image.*;
import java.util.*;
import java.util.List;

public class BitmapRenderer {

    public static boolean isColorDark(Color c) {
        int b = Math.max(c.getRed(), c.getGreen());
        b = Math.max(c.getBlue(), b);
        return b < 200;
    }

    public BufferedImage renderToImage(Diagram d, RenderOptions opt) {
        BufferedImage image;
        if (opt.needsTransparency()) image = new BufferedImage(d.getWidth(), d.getHeight(), BufferedImage.TYPE_INT_ARGB);
        else image = new BufferedImage(d.getWidth(), d.getHeight(), BufferedImage.TYPE_INT_RGB);
        return render(d, image, opt);
    }

    public BufferedImage render(Diagram d, BufferedImage image, RenderOptions opt) {
        BufferedImage result = image;
        Graphics2D g2 = image.createGraphics();
        Object aa = opt.antialias ? RenderingHints.VALUE_ANTIALIAS_ON : RenderingHints.VALUE_ANTIALIAS_OFF;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);

        g2.setColor(opt.background);
        g2.fillRect(0, 0, image.getWidth() + 10, image.getHeight() + 10);

        ArrayList<DiagramShape> shapes = d.getAllDiagramShapes();

        if (opt.dropShadows) {
            for (DiagramShape shape : shapes) {
                if (shape.getPoints().isEmpty()) continue;
                GeneralPath path = shape.makeIntoRenderPath(d, opt);
                float offset = d.getMinimumOfCellDimension() / 3.333f;
                if (path != null && shape.dropsShadow() && shape.getType() != DiagramShape.TYPE_CUSTOM) {
                    GeneralPath shadow = new GeneralPath(path);
                    AffineTransform tr = new AffineTransform();
                    tr.setToTranslation(offset, offset);
                    shadow.transform(tr);
                    g2.setColor(new Color(150, 150, 150));
                    g2.fill(shadow);
                }
            }
            int blurRadius = 6;
            int r2 = blurRadius * blurRadius;
            float weight = 1.0f / r2;
            float[] el = new float[r2];
            for (int k = 0; k < r2; k++) el[k] = weight;
            Kernel kernel = new Kernel(blurRadius, blurRadius, el);
            ConvolveOp blur = new ConvolveOp(kernel, ConvolveOp.EDGE_NO_OP, null);
            BufferedImage dest = new BufferedImage(image.getWidth(), image.getHeight(), image.getType());
            blur.filter(image, dest);
            g2 = (Graphics2D) dest.getGraphics();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
            result = dest;
        }

        float dashInterval = Math.min(d.getCellWidth(), d.getCellHeight()) / 2;
        float strokeWeight = d.getMinimumOfCellDimension() / 10;
        Stroke normalStroke = new BasicStroke(strokeWeight, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        Stroke dashStroke = new BasicStroke(strokeWeight, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND, 0, new float[]{dashInterval}, 0);

        ArrayList<DiagramShape> storage = new ArrayList<DiagramShape>();
        for (DiagramShape s : shapes) if (s.getType() == DiagramShape.TYPE_STORAGE) storage.add(s);
        Collections.sort(storage, new Shape3DOrderingComparator());

        g2.setStroke(normalStroke);
        for (DiagramShape s : storage) {
            GeneralPath path = s.makeIntoRenderPath(d, opt);
            if (!s.isStrokeDashed()) {
                g2.setColor(s.getFillColor() != null ? s.getFillColor() : Color.white);
                g2.fill(path);
            }
            g2.setStroke(s.isStrokeDashed() ? dashStroke : normalStroke);
            g2.setColor(s.getStrokeColor());
            g2.draw(path);
        }

        Collections.sort(shapes, new ShapeAreaComparator());

        ArrayList<DiagramShape> markers = new ArrayList<DiagramShape>();
        for (DiagramShape s : shapes) {
            if (s.getType() == DiagramShape.TYPE_POINT_MARKER) { markers.add(s); continue; }
            if (s.getType() == DiagramShape.TYPE_STORAGE) continue;
            if (s.getType() == DiagramShape.TYPE_CUSTOM) continue;
            if (s.getPoints().isEmpty()) continue;
            GeneralPath path = s.makeIntoRenderPath(d, opt);
            if (path != null && s.isClosed() && !s.isStrokeDashed()) {
                g2.setColor(s.getFillColor() != null ? s.getFillColor() : Color.white);
                g2.fill(path);
            }
            if (s.getType() != DiagramShape.TYPE_ARROWHEAD) {
                g2.setColor(s.getStrokeColor());
                g2.setStroke(s.isStrokeDashed() ? dashStroke : normalStroke);
                if (path != null) g2.draw(path);
            }
        }

        g2.setStroke(normalStroke);
        for (DiagramShape s : markers) {
            GeneralPath path = s.makeIntoRenderPath(d, opt);
            g2.setColor(Color.white);
            g2.fill(path);
            g2.setColor(s.getStrokeColor());
            g2.draw(path);
        }

        for (DText t : d.getTextObjects()) {
            g2.setFont(t.getFont());
            if (t.hasOutline()) {
                g2.setColor(t.getOutlineColor());
                g2.drawString(t.getText(), t.getX() + 1, t.getY());
                g2.drawString(t.getText(), t.getX() - 1, t.getY());
                g2.drawString(t.getText(), t.getX(), t.getY() + 1);
                g2.drawString(t.getText(), t.getX(), t.getY() - 1);
            }
            g2.setColor(t.getColor());
            g2.drawString(t.getText(), t.getX(), t.getY());
        }

        if (opt.debugLines) {
            Stroke debugStroke = new BasicStroke(1, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
            g2.setStroke(debugStroke);
            g2.setColor(new Color(170, 170, 170));
            g2.setXORMode(Color.white);
            for (int x = 0; x < d.getWidth(); x += d.getCellWidth()) g2.drawLine(x, 0, x, d.getHeight());
            for (int y = 0; y < d.getHeight(); y += d.getCellHeight()) g2.drawLine(0, y, d.getWidth(), y);
        }

        g2.dispose();
        return result;
    }

    static class ShapeAreaComparator implements Comparator<DiagramShape> {
        public int compare(DiagramShape a, DiagramShape b) {
            double x = a.calculateArea(), y = b.calculateArea();
            if (x > y) return -1;
            if (x < y) return 1;
            return 0;
        }
    }

    static class Shape3DOrderingComparator implements Comparator<DiagramShape> {
        public int compare(DiagramShape a, DiagramShape b) {
            double y1 = a.makeIntoPath().getBounds().getMaxY();
            double y2 = b.makeIntoPath().getBounds().getMaxY();
            if (y1 > y2) return -1;
            if (y1 < y2) return 1;
            return 0;
        }
    }
}
