        if (longOpts.containsKey(s)) { r.add(s); return r; }
        for (String l : longOpts.keySet()) if (l.startsWith(s)) r.add(l);
        return r;
    }

    private static String ambiguous(String opt, List<String> m) {
        StringBuilder b = new StringBuilder("Ambiguous option: '" + opt + "'  (could be: ");
        for (int i = 0; i < m.size(); i++) {
