            if (i < m.size() - 1) b.append(", ");
        }
        b.append(")");
        return b.toString();
    }

    private List<String> tokens;
    private Opt currentOption;

    private List<String> flatten(String[] arguments) throws ParseException {
        tokens = new ArrayList<String>();
        currentOption = null;
        for (String token : arguments) {
            if ("-".equals(token) || "--".equals(token)) {
                tokens.add(token);
            } else if (token.startsWith("--")) {
                int pos = token.indexOf('=');
                String opt = pos == -1 ? token : token.substring(0, pos);
