                    processOptionToken("-" + o.longName);
                } else {
                    burst(token);
                }
            } else {
                tokens.add(token);
            }
        }
        return tokens;
    }

    private void processOptionToken(String token) {
        if (hasOption(token)) currentOption = getOption(token);
        tokens.add(token);
    }

    private void burst(String token) {
        for (int i = 1; i < token.length(); i++) {
            String ch = String.valueOf(token.charAt(i));
