        return s;
    }

    void parse(String[] arguments) throws ParseException {
        List<String> list = flatten(arguments);
        ListIterator<String> it = list.listIterator();
        boolean eatTheRest = false;
        while (it.hasNext()) {
            String t = it.next();
            if ("--".equals(t)) eatTheRest = true;
            else if ("-".equals(t)) args.add(t);
            else if (t.startsWith("-")) processOption(t, it);
            else args.add(t);
            if (eatTheRest) {
                while (it.hasNext()) {
                    String s = it.next();
                    if (!"--".equals(s)) args.add(s);
                }
            }
        }
    }

    private void processOption(String arg, ListIterator<String> it) throws ParseException {
        if (!hasOption(arg)) throw new ParseException("Unrecognized option: " + arg);
        Opt o = getOption(arg).copy();
        if (o.hasArg) {
