                String s = it.next();
                if (hasOption(s) && s.startsWith("-")) { it.previous(); break; }
                if (o.value == null) o.value = stripQuotes(s);
                else { it.previous(); break; }
            }
            if (o.value == null) throw new ParseException("Missing argument for option: " + o.key());
        }
        parsed.add(o);
    }

    boolean has(String longName) {
        for (Opt o : parsed) if (longName.equals(o.longName)) return true;
        return false;
    }

    String value(String longName) {
        for (Opt o : parsed) if (longName.equals(o.longName)) return o.value;
        return null;
    }
}
