    static final String NOTICE = "ditaa version 0.11, Copyright (C) 2004--2017  Efstathios (Stathis) Sideris";

    private Main() {}

    static void printUsage(boolean lower) {
        System.out.print(Help.usage(lower));
        System.out.flush();
    }

    static Color parseColor(String hex) {
        if (hex.length() == 6) {
            return new Color(Integer.parseInt(hex, 16));
        } else if (hex.length() == 8) {
            return new Color(Integer.parseInt(hex.substring(0, 2), 16), Integer.parseInt(hex.substring(2, 4), 16),
                             Integer.parseInt(hex.substring(4, 6), 16), Integer.parseInt(hex.substring(6, 8), 16));
        }
        throw new IllegalArgumentException("Cannot interpret \"" + hex + "\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).");
    }

    static void buildOptions(Cli cli, RenderOptions ro, ProcessOptions po) throws UnsupportedEncodingException {
        po.verbose = cli.has("verbose");
        ro.dropShadows = !cli.has("no-shadows");
        po.printDebug = cli.has("debug");
        ro.debugLines = cli.has("debug");
        po.overwrite = cli.has("overwrite");
        if (cli.has("scale")) {
            Float scale = Float.parseFloat(cli.value("scale"));
            ro.scale = scale.floatValue();
        }
        po.allCornersRound = cli.has("round-corners");
        po.separateCommonEdges = !cli.has("no-separation");
        ro.antialias = !cli.has("no-antialias");
        ro.fixedSlope = cli.has("fixed-slope");
        if (cli.has("background")) ro.background = parseColor(cli.value("background"));
        if (cli.has("transparent")) ro.background = new Color(0, 0, 0, 0);
        if (cli.has("tabs")) {
            Integer t = Integer.parseInt(cli.value("tabs"));
            int v = t.intValue();
            if (v < 0) v = 0;
            po.tabSize = v;
        }
        String enc = cli.value("encoding");
        if (enc != null) {
            new String(new byte[2], enc);
            po.encoding = enc;
        }
        ro.svg = cli.has("svg");
        if (cli.has("svg-font-url")) ro.fontURL = cli.value("svg-font-url");
        po.html = cli.has("html");
    }

    static void printRunInfo(Cli cli) {
        System.out.println("\n" + NOTICE + "\n");
        System.out.println("Running with options:");
        for (Cli.Opt o : cli.parsed) {
            if (o.hasArg) System.out.println(o.longName + " = " + o.value);
            else System.out.println(o.longName);
        }
    }

    public static void main(String[] argv) {
        long startTime = System.currentTimeMillis();
        Cli cli = new Cli();
        try {
            cli.parse(argv);
        } catch (Cli.ParseException e) {
            System.err.println(e.getMessage());
            printUsage(false);
            System.exit(2);
        }
        if (cli.has("help") || argv.length == 0) {
            printUsage(false);
            System.exit(0);
        }
        RenderOptions ro = new RenderOptions();
        ProcessOptions po = new ProcessOptions();
        try {
            buildOptions(cli, ro, po);
        } catch (UnsupportedEncodingException e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(2);
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
            printUsage(false);
            System.exit(2);
        }
        String[] args = cli.args.toArray(new String[0]);
        if (args.length == 0) {
            System.err.println("Error: Please provide the input file filename");
            printUsage(true);
            System.exit(2);
        }

        if (po.html) {
            printRunInfo(cli);
            String filename = args[0];
            String toFilename;
            if (args.length == 1) toFilename = FileNames.makeTargetPathname(filename, "html", "_processed", true);
            else toFilename = args[1];
            File target = new File(toFilename);
            if (!po.overwrite && target.exists()) {
                System.out.println("Error: File " + toFilename + " exists. If you would like to overwrite it, please use the --overwrite option.");
                System.exit(0);
            }
            new HtmlConverter().convertHTMLFile(filename, toFilename, "ditaa_diagram", "images", ro, po);
            System.exit(0);
        }

        String fromFilename = args[0];
        boolean stdIn = "-".equals(fromFilename);
        String toFilename;
        boolean stdOut;
        String ext = ro.svg ? "svg" : "png";
        if (args.length == 1) {
            if (stdIn) { toFilename = "-"; stdOut = true; }
            else { toFilename = FileNames.makeTargetPathname(fromFilename, ext, po.overwrite); stdOut = false; }
        } else {
            toFilename = args[1];
            stdOut = "-".equals(toFilename);
        }

        if (!stdOut) {
            printRunInfo(cli);
            System.out.println("Reading " + (stdIn ? "standard input" : "file: " + fromFilename));
        }

        Grid grid;
        try {
            grid = GridLoader.load(fromFilename, po);
        } catch (UnsupportedEncodingException e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
            return;
        } catch (FileNotFoundException e) {
            System.err.println("Error: File " + fromFilename + " does not exist");
            System.exit(1);
            return;
        } catch (IOException e) {
            System.err.println("Error: Cannot open file " + fromFilename + " for reading");
            System.exit(1);
            return;
        }

        if (po.printDebug) {
            if (!stdOut) System.out.println("Using grid:");
            grid.printDebug(System.out);
        }

        Diagram diagram = new Diagram(grid, ro, po);

        if (!stdOut) System.out.println("Rendering to file: " + toFilename);

        if (ro.svg) {
            String content = new SvgRenderer().render(diagram, ro);
            try {
                if (stdOut) {
                    System.out.print(content);
                    System.out.flush();
                } else {
                    Writer w = new OutputStreamWriter(new FileOutputStream(toFilename));
                    w.write(content);
                    w.close();
                }
            } catch (IOException e) {
                System.err.println("Error: Cannot write to file " + toFilename);
                System.exit(1);
            }
        } else {
            BufferedImage image = new BitmapRenderer().renderToImage(diagram, ro);
            try {
                if (stdOut) {
                    ImageIO.write(image, "png", System.out);
                    System.out.flush();
                } else {
                    ImageIO.write(image, "png", new File(toFilename));
                }
            } catch (IOException e) {
                System.err.println("Error: Cannot write to file " + toFilename);
                System.exit(1);
            }
        }

        long endTime = System.currentTimeMillis();
        long total = (endTime - startTime) / 1000;
        if (!stdOut) System.out.println("Done in " + total + "sec");
    }
}
