package ditaa;

import java.io.File;

final class FileNames {
    private FileNames() {}

    static String makeTargetPathname(String source, String ext, boolean overwrite) {
        return makeTargetPathname(source, ext, "", overwrite);
    }

    static String makeTargetPathname(String source, String ext, String postfix, boolean overwrite) {
        File f = new File(source);
        String path = "";
        if (f.getParentFile() != null) {
            path = f.getParentFile().getAbsolutePath();
            if (!path.endsWith(File.separator)) path += File.separator;
        }
        String target = path + baseName(f.getName()) + postfix + "." + ext;
        if (new File(target).exists() && !overwrite) target = alternative(target);
        return target;
    }

    static String alternative(String p) {
        for (int i = 2; i <= 100; i++) {
            String alt = baseName(p) + "_" + i;
            String e = extension(p);
            if (e != null) alt += "." + e;
            if (!new File(alt).exists()) return alt;
        }
        return null;
    }

    static String extension(String p) {
        int i = p.lastIndexOf('.');
        return i == -1 ? null : p.substring(i + 1);
    }

    static String baseName(String p) {
        int i = p.lastIndexOf('.');
        return i == -1 ? p : p.substring(0, i);
    }
}
