package ditaa;

import java.io.*;
import java.util.*;

final class GridLoader {
    private GridLoader() {}

    static String readAll(InputStream is) throws IOException {
        ByteArrayOutputStream bo = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        int n;
        while ((n = is.read(buf)) > 0) bo.write(buf, 0, n);
        return new String(bo.toByteArray());
    }

    static Grid load(String filename, ProcessOptions po) throws IOException {
        InputStream is = "-".equals(filename) ? System.in : new FileInputStream(filename);
        String content = readAll(is);
        String[] arr = content.split("(\r)?\n");
        List<StringBuilder> lines = new ArrayList<StringBuilder>();
        for (String s : arr) lines.add(new StringBuilder(s));
        return fromLines(lines, po);
    }

    static boolean isBlank(String s) { return s.trim().isEmpty(); }

    static Grid fromLines(List<StringBuilder> lines, ProcessOptions po) throws UnsupportedEncodingException {
        int i;
        boolean done = false;
        for (i = lines.size() - 1; !done && i >= 0; i--) {
            if (!isBlank(lines.get(i).toString())) done = true;
        }
        List<StringBuilder> rows = new ArrayList<StringBuilder>(lines.subList(0, Math.min(lines.size(), i + 2)));
        if (rows.isEmpty()) rows.add(new StringBuilder());

        fixTabs(rows, po.tabSize);

        int border = 2;
        int maxLength = 0;
        String enc = po.encoding;
        for (int k = 0; k < rows.size(); k++) {
            String row = rows.get(k).toString();
            if (enc != null) {
                byte[] bytes = row.getBytes();
                row = new String(bytes, enc);
            }
            if (row.length() > maxLength) maxLength = row.length();
            rows.set(k, new StringBuilder(row));
        }
        List<StringBuilder> out = new ArrayList<StringBuilder>();
        String tb = Grid.spaces(maxLength + border * 2);
        out.add(new StringBuilder(tb));
        out.add(new StringBuilder(tb));
        for (StringBuilder row : rows) {
            StringBuilder nr = new StringBuilder();
            nr.append("  ").append(row).append(Grid.spaces(maxLength - row.length())).append("  ");
            out.add(nr);
        }
        out.add(new StringBuilder(tb));
        out.add(new StringBuilder(tb));
        Grid g = new Grid();
        g.setRows(out);
        g.replaceBullets();
        g.replaceHumanColorCodes();
        return g;
    }

    static void fixTabs(List<StringBuilder> rows, int tabSize) {
        for (int r = 0; r < rows.size(); r++) {
            String row = rows.get(r).toString();
            StringBuilder nr = new StringBuilder();
            for (int i = 0; i < row.length(); i++) {
                char c = row.charAt(i);
                if (c == '\t') {
                    int left = tabSize - nr.length() % tabSize;
                    nr.append(Grid.spaces(left));
                } else nr.append(c);
            }
            rows.set(r, nr);
        }
    }
}
