/** Compiles the sources and packages them into a self-launching executable. */
public class Build {
    public static void main(String[] a) throws Exception {
        Path root = Paths.get(a.length > 0 ? a[0] : ".").toAbsolutePath().normalize();
        Path src = root.resolve("src");
        Path classes = root.resolve("build/classes");
        if (Files.exists(classes)) {
            try (Stream<Path> w = Files.walk(classes)) {
                w.sorted(Comparator.reverseOrder()).forEach(p -> p.toFile().delete());
            }
        }
        Files.createDirectories(classes);
        List<File> files;
        try (Stream<Path> w = Files.walk(src)) {
            files = w.filter(p -> p.toString().endsWith(".java")).map(Path::toFile).collect(Collectors.toList());
        }
        JavaCompiler jc = ToolProvider.getSystemJavaCompiler();
        if (jc == null) throw new IllegalStateException("no system java compiler");
        StandardJavaFileManager fm = jc.getStandardFileManager(null, null, null);
        List<String> opts = Arrays.asList("-d", classes.toString(), "-encoding", "UTF-8", "-nowarn", "-Xlint:none");
        boolean ok = jc.getTask(null, fm, null, opts, null, fm.getJavaFileObjectsFromFiles(files)).call();
        if (!ok) { System.err.println("compilation failed"); System.exit(1); }

        ByteArrayOutputStream jarBytes = new ByteArrayOutputStream();
        Manifest mf = new Manifest();
        mf.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
        mf.getMainAttributes().put(Attributes.Name.MAIN_CLASS, "ditaa.Main");
        try (JarOutputStream jos = new JarOutputStream(jarBytes, mf)) {
            List<Path> cls;
            try (Stream<Path> w = Files.walk(classes)) {
                cls = w.filter(Files::isRegularFile).sorted().collect(Collectors.toList());
            }
            for (Path p : cls) {
                String name = classes.relativize(p).toString().replace(File.separatorChar, '/');
                JarEntry e = new JarEntry(name);
                e.setTime(0);
                jos.putNextEntry(e);
                jos.write(Files.readAllBytes(p));
                jos.closeEntry();
            }
        }
        Files.write(root.resolve("build/ditaa.jar"), jarBytes.toByteArray());

        String stub = "#!/bin/sh\nexec java -jar \"$0\" \"$@\"\n";
        Path exe = root.resolve("executable");
        try (OutputStream os = Files.newOutputStream(exe)) {
            os.write(stub.getBytes("US-ASCII"));
            os.write(jarBytes.toByteArray());
        }
        exe.toFile().setExecutable(true, false);
        System.out.println("built " + exe);
    }
}
