package ditaa;

import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import javax.imageio.ImageIO;
import javax.swing.text.MutableAttributeSet;
import javax.swing.text.html.HTML;
import javax.swing.text.html.HTMLEditorKit;
import javax.swing.text.html.parser.ParserDelegator;

/** Replaces text diagrams embedded in HTML with rendered images. */
final class HtmlConverter {
    private static final String TAG_CLASS = "textdiagram";

    private static final class Block {
        int start = -1, contentStart = -1, contentEnd = -1, end = -1;
        String id;
    }

    static String readFile(String filename) throws IOException {
        try (InputStream is = new FileInputStream(filename)) {
            return GridLoader.readAll(is);
        }
    }

    private static int endOfTag(String s, int from) {
        char quote = 0;
        for (int i = from; i < s.length(); i++) {
            char c = s.charAt(i);
            if (quote != 0) { if (c == quote) quote = 0; continue; }
            if (c == '"' || c == '\'') { quote = c; continue; }
            if (c == '>') return i;
        }
        return s.length() - 1;
    }

    private List<Block> findBlocks(final String text) throws IOException {
        final List<Block> blocks = new ArrayList<Block>();
        HTMLEditorKit.ParserCallback cb = new HTMLEditorKit.ParserCallback() {
            Block current = null;
            @Override public void handleStartTag(HTML.Tag t, MutableAttributeSet a, int pos) {
                if (t == HTML.Tag.PRE) {
                    Object cls = a.getAttribute(HTML.Attribute.CLASS);
                    if (cls != null && TAG_CLASS.equals(cls.toString())) {
                        Block b = new Block();
                        b.start = pos;
                        b.contentStart = endOfTag(text, pos) + 1;
                        Object id = a.getAttribute(HTML.Attribute.ID);
                        b.id = id == null ? null : id.toString();
                        current = b;
                    }
                }
            }
            @Override public void handleEndTag(HTML.Tag t, int pos) {
                if (t == HTML.Tag.PRE && current != null) {
                    current.contentEnd = pos;
                    current.end = endOfTag(text, pos) + 1;
                    blocks.add(current);
                    current = null;
                }
            }
        };
        new ParserDelegator().parse(new StringReader(text), cb, true);
        return blocks;
    }

    void convertHTMLFile(String filename, String targetFilename, String imageBaseFilename, String imageDirName,
                         RenderOptions ro, ProcessOptions po) {
        String htmlText;
        try {
            htmlText = readFile(filename);
        } catch (IOException e) {
            System.err.println("Error: Cannot read file " + filename);
            return;
        }
        System.out.print("Converting HTML file (" + filename + " -> " + targetFilename + ")... ");
        List<Block> blocks;
        try {
            blocks = findBlocks(htmlText);
        } catch (IOException e) {
            blocks = new ArrayList<Block>();
        }
        if (blocks.isEmpty()) {
            System.out.println("\nHTML document does not contain any <pre> tags with their class attribute set to \"" + TAG_CLASS + "\". Nothing to do.");
            return;
        }
        HashMap<String, String> nameMap = new HashMap<String, String>();
        StringBuilder out = new StringBuilder();
        int last = 0, counted = 0;
        for (Block b : blocks) {
            String name;
            if (b.id != null) name = b.id.replace(' ', '_');
            else { counted++; name = imageBaseFilename + "_" + counted; }
            String key = imageDirName + "/" + name + ".png";
            String content = htmlText.substring(Math.min(b.contentStart, b.contentEnd), b.contentEnd);
            nameMap.put(key, content);
            out.append(htmlText, last, b.start);
            out.append("<img src=\"").append(key).append("\" />");
            last = b.end;
        }
        out.append(htmlText.substring(Math.min(last, htmlText.length())));
        try (Writer w = new OutputStreamWriter(new FileOutputStream(targetFilename))) {
            w.write(out.toString());
        } catch (IOException e) {
            System.err.println("Error: Cannot write to file " + targetFilename);
            return;
        }
        System.out.println("done");
        System.out.println("Generating diagrams... ");

        String parent = new File(targetFilename).getParent();
        File imageDir = new File(parent + File.separator + imageDirName);
        if (!imageDir.exists()) {
            if (!imageDir.mkdir()) {
                System.err.println("Could not create directory " + imageDirName);
                return;
            }
        }
        for (Map.Entry<String, String> e : nameMap.entrySet()) {
            String key = e.getKey();
            String path = parent + File.separator + key;
            if (new File(path).exists() && !po.overwrite) {
                System.out.println("Error: Cannot overwrite file " + key + ", file already exists. Use the --overwrite option if you would like to allow file overwrite.");
                continue;
            }
            Grid grid;
            try {
                grid = GridLoader.fromText(e.getValue(), po);
            } catch (UnsupportedEncodingException ex) {
                System.err.println("Error: " + ex.getMessage());
                continue;
            }
            Diagram diagram = new Diagram(grid, ro, po);
            BufferedImage image = new BitmapRenderer().renderToImage(diagram, ro);
            try {
                ImageIO.write(image, "png", new File(path));
            } catch (IOException ex) {
                ex.printStackTrace();
                System.err.println("Error: Cannot write to file " + filename + " -- skipping");
                continue;
            }
            System.out.println("\t" + path);
        }
        System.out.println("\n...done");
    }
}
