    /** A parsed start tag: attributes (first occurrence wins) and end offset (exclusive). */
    private static final class Tag {
        int end;
        LinkedHashMap<String, String> attrs = new LinkedHashMap<String, String>();
    }

    private static String decodeEntities(String v) {
        if (v.indexOf('&') < 0) return v;
        StringBuilder b = new StringBuilder();
        int i = 0;
        while (i < v.length()) {
            char c = v.charAt(i);
            if (c == '&') {
                int semi = v.indexOf(';', i);
                if (semi > i) {
                    String ent = v.substring(i + 1, semi);
                    String rep = null;
                    if (ent.equals("amp")) rep = "&";
                    else if (ent.equals("lt")) rep = "<";
                    else if (ent.equals("gt")) rep = ">";
                    else if (ent.equals("quot")) rep = "\\"";
                    else if (ent.equals("apos")) rep = "'";
                    else if (ent.equals("nbsp")) rep = "\\u00a0";
                    else if (ent.startsWith("#x") || ent.startsWith("#X")) {
                        try { rep = new String(Character.toChars(Integer.parseInt(ent.substring(2), 16))); } catch (Exception e) { rep = null; }
                    } else if (ent.startsWith("#")) {
                        try { rep = new String(Character.toChars(Integer.parseInt(ent.substring(1)))); } catch (Exception e) { rep = null; }
                    }
                    if (rep != null) { b.append(rep); i = semi + 1; continue; }
                }
            }
            b.append(c);
            i++;
        }
        return b.toString();
    }

    /** Parses the attributes of a start tag whose name ends at position i. */
    private static Tag parseTag(String s, int i) {
        Tag t = new Tag();
        int n = s.length();
        while (i < n) {
            char c = s.charAt(i);
            if (c == '>') { t.end = i + 1; return t; }
            if (Character.isWhitespace(c) || c == '/') { i++; continue; }
            if (isNameChar(c)) {
                int ns = i;
                while (i < n && isNameChar(s.charAt(i))) i++;
                String name = s.substring(ns, i).toLowerCase(Locale.ROOT);
                int j = i;
                while (j < n && Character.isWhitespace(s.charAt(j))) j++;
                String value = null;
                if (j < n && s.charAt(j) == '=') {
                    j++;
                    while (j < n && Character.isWhitespace(s.charAt(j))) j++;
                    if (j < n && (s.charAt(j) == '"' || s.charAt(j) == '\\'')) {
                        char q = s.charAt(j);
                        int close = s.indexOf(q, j + 1);
                        if (close < 0) close = n;
                        value = s.substring(j + 1, close);
                        i = Math.min(n, close + 1);
                    } else {
                        int vs = j;
                        while (j < n && !Character.isWhitespace(s.charAt(j)) && s.charAt(j) != '>') j++;
                        value = s.substring(vs, j);
                        i = j;
                    }
                    value = decodeEntities(value);
                }
                if (!t.attrs.containsKey(name)) t.attrs.put(name, value);
                continue;
            }
            i++;
        }
        t.end = n;
        return t;
    }

    private static boolean isTagNameEnd(String s, int i) {
        if (i >= s.length()) return true;
        char c = s.charAt(i);
        return Character.isWhitespace(c) || c == '>' || c == '/';
    }

    /** Finds the end tag matching the pre start tag ending at 'from'; returns {start, end} or null. */
    private static int[] findEndTag(String s, int from) {
        int depth = 0;
        int i = from;
        int n = s.length();
        while (i < n) {
            if (s.startsWith("<!--", i)) {
                int e = s.indexOf("-->", i + 4);
                if (e < 0) return null;
                i = e + 3;
                continue;
            }
            if (s.charAt(i) == '<') {
                if (startsWithIgnoreCase(s, i, "</pre") && isTagNameEnd(s, i + 5)) {
                    int gt = s.indexOf('>', i);
                    if (gt < 0) return null;
                    if (depth == 0) return new int[]{i, gt + 1};
                    depth--;
                    i = gt + 1;
                    continue;
                }
                if (startsWithIgnoreCase(s, i, "<pre") && isTagNameEnd(s, i + 4)) {
                    Tag t = parseTag(s, i + 4);
                    depth++;
                    i = t.end;
                    continue;
                }
            }
            i++;
        }
        return null;
    }

    private List<Block> findBlocks(final String text) {
        List<Block> blocks = new ArrayList<Block>();
        int i = 0, n = text.length();
        while (i < n) {
            if (text.startsWith("<!--", i)) {
                int e = text.indexOf("-->", i + 4);
                if (e < 0) break;
                i = e + 3;
                continue;
            }
            if (text.charAt(i) == '<' && startsWithIgnoreCase(text, i, "<pre") && isTagNameEnd(text, i + 4)) {
                Tag t = parseTag(text, i + 4);
                String cls = t.attrs.get("class");
                if (TAG_CLASS.equals(cls)) {
                    Block b = new Block();
                    b.start = i;
                    b.contentStart = t.end;
                    b.id = t.attrs.get("id");
                    int[] et = findEndTag(text, t.end);
                    if (et == null) {
                        b.contentEnd = t.end;
                        b.end = t.end;
                    } else {
                        b.contentEnd = et[0];
                        b.end = et[1];
                    }
                    blocks.add(b);
                    i = b.end;
                    continue;
                }
                i = t.end;
                continue;
            }
            i++;
        }
        return blocks;
    }

