        by = rnd.randint(b[1]+1, b[3]-1) if b[3]-b[1] > 1 else None
        if ay is None or by is None: continue
        if a[2] < b[0]:
            sx, ex = a[2], b[0]
            if ay == by:
                for x in range(sx+1, ex): 
