                if mx is None: continue
                path = [(x, ay) for x in range(sx+1, mx)] + [(mx, y) for y in range(min(ay,by), max(ay,by)+1)] + [(x, by) for x in range(mx+1, ex)]
                if any(cv.get(x, y) != ' ' for (x, y) in path): continue
                for x in range(sx+1, mx): cv.put(x, ay, '-')
                for x in range(mx+1, ex): cv.put(x, by, '-')
                for y in range(min(ay,by)+1, max(ay,by)): cv.put(mx, y, '|')
                cv.put(mx, ay, '+'); cv.put(mx, by, '+')
                if rnd.random() < 0.3: cv.put(mx, ay, '/' if by > ay else '\\') if False else None
                cv.put(sx, ay, '+')
                if rnd.random() < 0.7: cv.put(ex-1, by, '>')
                if rnd.random() < 0.3:
                    cv.put(mx, (ay+by)//2, '*') if abs(ay-by) > 2 else None
    # free floating lines and text
    for _ in range(rnd.randint(0, 4)):
        x, y = rnd.randint(0, w-1), rnd.randint(0, h-1)
        kind = rnd.random()
        if kind < 0.3:
            l = rnd.randint(2, 10)
            if all(cv.get(x+i, y) == ' ' for i in range(-1, l+1)):
                for i in range(l): cv.put(x+i, y, '-' if rnd.random() > 0.1 else '=')
                if rnd.random() < 0.5: cv.put(x+l-1, y, '>')
        elif kind < 0.6:
            l = rnd.randint(2, 6)
            if all(cv.get(x, y+i) == ' ' for i in range(-1, l+1)):
                for i in range(l): cv.put(x, y+i, '|' if rnd.random() > 0.1 else ':')
                if rnd.random() < 0.5: cv.put(x, y+l-1, 'v')
                if rnd.random() < 0.3: cv.put(x, y, '^')
        else:
            t = rnd.choice(WORDS) + (' ' + rnd.choice(WORDS) if rnd.random() < 0.4 else '')
            if all(cv.get(x+i, y) == ' ' for i in range(-1, len(t)+1)):
                cv.text(x, y, t)
    return cv.render()

if __name__ == '__main__':
    out = sys.argv[1]; start = int(sys.argv[2]); n = int(sys.argv[3])
    os.makedirs(out, exist_ok=True)
    for i in range(start, start+n):
        with open(os.path.join(out, 'g%04d.txt' % i), 'w') as f: f.write(gen(i))
