import random, sys, os
sys.path.insert(0, '/tmp/gen')
from gen import Canvas, WORDS, COLORS, TAGS, box

def table(cv, x0, y0, cols, rows, rnd):
    # grid of cells sharing edges
    xs = [x0]
    for c in range(cols): xs.append(xs[-1] + rnd.randint(3, 9))
    ys = [y0]
    for r in range(rows): ys.append(ys[-1] + rnd.randint(2, 4))
    if xs[-1] >= cv.w or ys[-1] >= cv.h: return False
    for y in ys:
        for x in range(xs[0], xs[-1] + 1): cv.put(x, y, '-')
    for x in xs:
        for y in range(ys[0], ys[-1] + 1): cv.put(x, y, '|')
    for x in xs:
        for y in ys: cv.put(x, y, '+')
    if rnd.random() < 0.3:
        cv.put(xs[0], ys[0], '/'); cv.put(xs[-1], ys[0], '\\'); cv.put(xs[0], ys[-1], '\\'); cv.put(xs[-1], ys[-1], '/')
    for c in range(cols):
        for r in range(rows):
            iw = xs[c+1] - xs[c] - 1
            if rnd.random() < 0.4:
                t = rnd.choice(COLORS) if rnd.random() < 0.5 else rnd.choice(WORDS)
                if len(t) <= iw: cv.text(xs[c] + 1 + rnd.randint(0, iw - len(t)), ys[r] + 1, t)
    # random removal of an inner edge segment to create merged cells
    if rnd.random() < 0.3 and cols > 1:
        c = rnd.randint(1, cols - 1); r = rnd.randint(0, rows - 1)
        for y in range(ys[r] + 1, ys[r+1]): cv.put(xs[c], y, ' ')
    cv.mark(xs[0], ys[0], xs[-1], ys[-1])
    return True

def nested(cv, x0, y0, w, h, rnd):
    if x0 + w >= cv.w or y0 + h >= cv.h: return False
    box(cv, x0, y0, x0 + w, y0 + h, rnd)
    if w > 8 and h > 4:
        ix0, iy0 = x0 + rnd.randint(2, 3), y0 + rnd.randint(2, 2)
        ix1, iy1 = x0 + w - rnd.randint(2, 3), y0 + h - 1
        if ix1 - ix0 >= 3 and iy1 - iy0 >= 2:
            for y in range(iy0, iy1 + 1):
                for x in range(ix0, ix1 + 1): cv.put(x, y, ' ')
            box(cv, ix0, iy0, ix1, iy1, rnd)
    cv.mark(x0, y0, x0 + w, y0 + h)
    return True

def textblock(cv, x0, y0, rnd):
    n = rnd.randint(2, 4)
    align = rnd.choice(['left', 'right', 'center', 'bullet'])
    lines = []
    for i in range(n):
        t = rnd.choice(WORDS) + (' ' + rnd.choice(WORDS) if rnd.random() < 0.5 else '')
        if align == 'bullet': t = rnd.choice(['o ', '* ']) + t
        lines.append(t)
    wmax = max(len(l) for l in lines)
    if x0 + wmax + 1 >= cv.w or y0 + n >= cv.h: return False
    if not cv.free(x0, y0, x0 + wmax, y0 + n - 1): return False
    for i, l in enumerate(lines):
        if align == 'right': cv.text(x0 + wmax - len(l), y0 + i, l)
        elif align == 'center': cv.text(x0 + (wmax - len(l)) // 2, y0 + i, l)
        else: cv.text(x0, y0 + i, l)
    cv.mark(x0, y0, x0 + wmax, y0 + n - 1)
    return True

def gen(seed):
    rnd = random.Random(seed)
    w, h = rnd.randint(20, 70), rnd.randint(8, 28)
    cv = Canvas(w, h)
    for _ in range(rnd.randint(1, 5)):
        k = rnd.random()
        x0, y0 = rnd.randint(0, w - 6), rnd.randint(0, h - 4)
        if k < 0.35:
            if cv.free(x0, y0, min(w-1, x0 + 30), min(h-1, y0 + 10)):
                table(cv, x0, y0, rnd.randint(1, 4), rnd.randint(1, 3), rnd)
        elif k < 0.6:
            ww, hh = rnd.randint(6, 20), rnd.randint(3, 8)
            if cv.free(x0, y0, min(w-1, x0 + ww), min(h-1, y0 + hh)):
                nested(cv, x0, y0, ww, hh, rnd)
        elif k < 0.8:
            textblock(cv, x0, y0, rnd)
        else:
            ww, hh = rnd.randint(4, 14), rnd.randint(2, 5)
            if x0 + ww < w and y0 + hh < h and cv.free(x0, y0, x0 + ww, y0 + hh):
                box(cv, x0, y0, x0 + ww, y0 + hh, rnd); cv.mark(x0, y0, x0 + ww, y0 + hh)
                # add arrow out of the box
                yy = rnd.randint(y0 + 1, y0 + hh - 1) if hh > 1 else None
                if yy is not None and x0 + ww + 6 < w:
                    if all(cv.get(x, yy) == ' ' for x in range(x0 + ww + 1, x0 + ww + 6)):
                        cv.put(x0 + ww, yy, '+')
                        for x in range(x0 + ww + 1, x0 + ww + 5): cv.put(x, yy, '-')
                        cv.put(x0 + ww + 5, yy, '>' if rnd.random() < 0.6 else '*')
    return cv.render()

if __name__ == '__main__':
    out = sys.argv[1]; start = int(sys.argv[2]); n = int(sys.argv[3])
    os.makedirs(out, exist_ok=True)
    for i in range(start, start + n):
        with open(os.path.join(out, 'k%04d.txt' % i), 'w') as f: f.write(gen(i))
