            else:
                # L-shaped: down from b then right/left to b2's top
                pass
        if (c + 1, r) in grid and rnd.random() < 0.6:
            b2 = grid[(c + 1, r)]
            lo = max(b[1], b2[1]) + 1; hi = min(b[3], b2[3]) - 1
            if lo <= hi:
                y = rnd.randint(lo, hi)
                x0, x1 = b[2], b2[0]
                if x1 - x0 >= 2 and all(cv.get(x, y) == ' ' for x in range(x0 + 1, x1)):
