                ya = rnd.randint(b[1] + 1, b[3] - 1) if b[3] - b[1] > 1 else None
                yb = rnd.randint(b2[1] + 1, b2[3] - 1) if b2[3] - b2[1] > 1 else None
                if ya is not None and yb is not None and b2[0] - b[2] >= 4:
