                    path = [(x, ya) for x in range(b[2] + 1, mx + 1)] + [(mx, y) for y in range(min(ya, yb), max(ya, yb) + 1)] + [(x, yb) for x in range(mx, b2[0])]
                    if all(cv.get(x, y) == ' ' for (x, y) in path):
                        cv.put(b[2], ya, '+')
                        for x in range(b[2] + 1, mx): cv.put(x, ya, '-')
