    if rnd.random() < 0.5:
        t = ' '.join(rnd.choice(WORDS) for _ in range(rnd.randint(1, 3)))
        y = h - 1
        if all(cv.get(x, y) == ' ' for x in range(1, min(w - 1, len(t) + 2))):
